// Output Formatter - Handles both Alfred responses and specialist data
const input = $input.first().json;

// Check if this is a templated response (from specialists like !intel, !price, etc.)
if (input.output && typeof input.output === 'string') {
    // This is already a formatted response from the Templated Response Generator
    console.log(`📤 Passing through templated response (${input.template_type || 'unknown'})`);

    return [{
        json: {
            output: input.output,
            content: input.content,
            authorName: input.authorName,
            authorId: input.authorId,
            channelId: input.channelId,
            is_dm: input.is_dm,
            query_source: input.query_source,
            template_type: input.template_type,
            has_error: input.has_error || false
        }
    }];
}

// Check if this is a help response
if (input.specialist_data?.response_type === 'invalid_command_help') {
    console.log(`📤 Formatting help response for invalid command: !${input.specialist_data.invalid_command}`);

    return [{
        json: {
            output: input.specialist_data.help_message,
            content: input.content,
            authorName: input.authorName,
            authorId: input.authorId,
            channelId: input.channelId,
            is_dm: input.is_dm,
            query_source: input.query_source,
            template_type: 'help_response',
            has_error: false
        }
    }];
}

// This is a regular Alfred conversational response
let alfredResponse = '';

if (input.text && typeof input.text === 'string') {
    alfredResponse = input.text;
} else if (input.response && typeof input.response === 'string') {
    alfredResponse = input.response;
} else if (input.content && typeof input.content === 'string') {
    alfredResponse = input.content;
} else {
    alfredResponse = "I'm afraid something went awry with my response system, old chap!";
}

// Clean up the response - remove any excessive formatting
alfredResponse = alfredResponse
    .replace(/^\*\*Alfred:\*\*\s*/i, '') // Remove "Alfred:" prefix if present
    .replace(/^Alfred:\s*/i, '')        // Remove "Alfred:" prefix (non-bold)
    .trim();

// Ensure Discord character limit compliance (2000 chars)
if (alfredResponse.length > 1900) {
    alfredResponse = alfredResponse.substring(0, 1890) + "...\n\n*Response truncated for Discord limits*";
}

console.log(`📤 Formatted Alfred conversational response (${alfredResponse.length} chars)`);

return [{
    json: {
        output: alfredResponse,
        content: input.content,
        authorName: input.authorName,
        authorId: input.authorId,
        channelId: input.channelId,
        is_dm: input.is_dm,
        query_source: input.query_source || 'general_chat',
        template_type: 'alfred_conversation',
        has_error: false
    }
}];

// Updated Command Parser - Help for any unrecognized ! command
const input = $input.first().json;
const content = input.content || '';

// Remove the '!' prefix and split the command from its arguments
const args = content.substring(1).trim().split(' ');
const command = args.shift().toLowerCase(); // The first word is the command

let output = {
  ...input, // Pass along all original data like author, channelID, etc.
  type: 'general', // Default to general if command is not recognized or invalid
  query_source: 'command_express'
};

// Use a switch to handle different commands with validation
switch (command) {
  case 'price':
    const itemName = args.join(' ').trim();
    if (itemName) {
      output.type = 'price';
      output.items = itemName;
    } else {
      output.type = 'general';
      output.error_message = 'Please specify an item name. Example: !price Venture';
    }
    break;

  case 'intel':
    const characterName = args.join(' ').trim();
    if (characterName) {
      output.type = 'character';
      output.character_name = characterName;
    } else {
      output.type = 'general';
      output.error_message = 'Please specify a character name. Example: !intel Samalya Birchall';
    }
    break;

  case 'route':
    const routeArgs = args.join(' ');
    let routeParts;
    
    // Support multiple formats: "jita > amarr", "jita to amarr", "jita amarr"
    if (routeArgs.includes('>')) {
      routeParts = routeArgs.split('>');
    } else if (routeArgs.includes(' to ')) {
      routeParts = routeArgs.split(' to ');
    } else {
      // Split on space and take first and last words
      const words = routeArgs.trim().split(/\s+/);
      if (words.length >= 2) {
        routeParts = [words[0], words[words.length - 1]];
      } else {
        routeParts = [];
      }
    }
    
    if (routeParts.length === 2 && routeParts[0].trim() && routeParts[1].trim()) {
      output.type = 'route';
      output.origin = routeParts[0].trim();
      output.destination = routeParts[1].trim();
    } else {
      output.type = 'general';
      output.error_message = 'Please specify route format. Examples: !route Jita > Amarr, !route Jita to Amarr, or !route Jita Amarr';
    }
    break;

    // --- NEW: Add aliases for system and region commands ---
    case 'sys':
    case 'system':
    case 'reg':
    case 'region':
        const locationName = args.join(' ').trim();
        if (locationName) {
            output.type = 'system';
            output.system_name = locationName;
        } else {
            output.type = 'general';
            output.error_message = 'Please specify a system or region name. Example: !system Jita or !region Lonetrek';
        }
        break;

  default:
    // ANY other ! command gets flagged as help
    console.log(`❓ Unknown command detected: !${command} - flagging for help`);
    output.type = 'help';
    output.invalid_command = command;
    output.original_content = content;
    break;
}

console.log(`⚙️ Command Parser: !${command} → type: ${output.type}`);

// Return the structured JSON object
return [{ json: output }];

// Clean Author Name - capitalize first letters, remove trailing numbers
const input = $input.first().json;

function cleanAuthorName(name) {
  if (!name || typeof name !== 'string') return name;

  // Remove trailing numbers (e.g., "nate7170" -> "nate")
  let cleaned = name.replace(/\d+$/, '');

  // Capitalize first letter of each word
  cleaned = cleaned.replace(/\b\w/g, letter => letter.toUpperCase());

  return cleaned;
}

const output = {
  ...input,
  authorName: cleanAuthorName(input.authorName)
};

return [{ json: output }];

const items = $input.all();
console.log("--- DEBUG: Items received by 'Combine Data' ---");
console.log(JSON.stringify(items, null, 2));
console.log("-------------------------------------------------");

// Find the item with the original data (e.g., the user's query and authorId).
const originalDataItem = items.find(item => typeof item.json?.content === 'string' && item.json?.authorId);

// Find the item containing the embedding from the Google AI HTTP Request node.
// The embedding is at .json.embedding.values
let embeddingData = items.find(item => Array.isArray(item.json?.embedding?.values));

// --- Robust Debugging Checks ---
if (!originalDataItem) {
  console.error("❌ 'originalDataItem' was NOT found.");
  console.log("Looking for an item with 'json.content' (string) and 'json.authorId'.");
} else {
  console.log("✅ 'originalDataItem' found.");
}

if (!embeddingData) {
  console.error("❌ 'embeddingData' was NOT found.");
  console.log("Looking for an item with 'json.embedding.values' (Array).");
} else {
  console.log("✅ 'embeddingData' found. Embedding has", embeddingData.json.embedding.values.length, "dimensions.");
}
// ---------------------------------

// Critical validation: If either the original data or the embedding is missing, stop the workflow.
if (!originalDataItem || !embeddingData) {
  throw new Error('Critical data missing. Check the console logs above to see which item was not found.');
}

// Safely extract the query_embedding from the .values property.
const queryEmbedding = embeddingData.json.embedding.values;

// Further validation for the extracted embedding array.
if (!Array.isArray(queryEmbedding) || queryEmbedding.length === 0 || queryEmbedding.some(val => typeof val !== 'number' || isNaN(val))) {
    console.error("❌ Extracted query_embedding is not a valid array of numbers.");
    console.log("DEBUG: Invalid queryEmbedding value:", JSON.stringify(queryEmbedding, null, 2));
    throw new Error('Extracted query_embedding is malformed or empty.');
}

// Combine original data with the new query_embedding.
return [{
  json: {
    ...originalDataItem.json, // Spread all properties from the original item
    query_embedding: queryEmbedding, // Add the extracted query embedding
  }
}];

// Essential Memory Storage - Replace your "Prepare Storage Payload" node
// Focused on core conversational intelligence without over-engineering

const input = $input.first().json;

// Validate required fields
if (!input.content || !input.output || !input.authorId) {
  throw new Error('❌ Input data is missing required fields: content, output, or authorId.');
}

// ESSENTIAL 1: Extract key entities (people, ships, systems, topics)
function extractEssentialEntities(text) {
  const entities = {};

  // Pilot names (2-3 capitalized words)
  const pilotMatches = text.match(/\b[A-Z][a-z]{2,12}(?:\s+[A-Z][a-z]{2,12}){0,2}\b/g) || [];
  entities.pilots = pilotMatches.filter(name => 
    name.length > 3 && name.length < 25 && 
    !['Alfred', 'Jita', 'Amarr', 'Caldari', 'Gallente', 'Discord'].includes(name)
  );

  // EVE items/ships (expanded list)
  const eveTerms = ['venture', 'plex', 'raven', 'drake', 'golem', 'caracal', 'tritanium', 'mining', 'ore', 'asteroid'];
  entities.items = eveTerms.filter(term => text.toLowerCase().includes(term));

  // Major systems
  const systems = ['jita', 'amarr', 'dodixie', 'rens', 'hek', 'perimeter'];
  entities.systems = systems.filter(sys => text.toLowerCase().includes(sys));

  // General conversation topics (NEW!)
  const topics = ['pizza', 'pineapple', 'secret', 'food', 'preference', 'ingredient', 'topping'];
  entities.topics = topics.filter(topic => text.toLowerCase().includes(topic));

  return entities;
}

// ESSENTIAL 2: Simple intent classification (just the basics)
function getBasicIntent(content) {
  const text = content.toLowerCase();

  if (text.includes('price') || text.includes('cost') || text.includes('market')) return 'pricing';
  if (text.includes('intel') || text.includes('threat') || text.includes('pilot')) return 'intel';
  if (text.includes('route') || text.includes('jump') || text.includes('travel')) return 'routing';
  if (text.includes('hello') || text.includes('hi') || text.includes('hey')) return 'greeting';

  return 'general';
}

// ESSENTIAL 3: Basic conversation threading (simple but effective)
function generateConversationContext(input) {
  const entities = extractEssentialEntities(input.content);
  const intent = getBasicIntent(input.content);

  // Create a simple "conversation signature" for threading
  const signature = {
    primary_entities: [...entities.pilots, ...entities.items, ...entities.systems].slice(0, 3),
    intent: intent,
    has_question: input.content.includes('?'),
    is_follow_up: /\b(that|this|the same|also|too|as well)\b/i.test(input.content)
  };

  return signature;
}

// Build the essential memory payload
const timestamp = input.timestamp || new Date().toISOString();
const entities = extractEssentialEntities(input.content);
const intent = getBasicIntent(input.content);
const conversationContext = generateConversationContext(input);

// Rich conversation text for embedding (includes context)
const entityContext = Object.values(entities).flat().join(' ');
const conversationText = `User (${intent}): "${input.content}"\nAlfred: "${input.output}"\nEntities: ${entityContext}`;

// Essential metadata only
const essentialPayload = {
  // Core conversation
  conversation_text: conversationText,
  user_query: input.content,
  alfred_response: input.output,

  // Essential context
  intent: intent,
  entities: entities,
  conversation_signature: conversationContext,

  // Basic metadata
  author_id: input.authorId,
  author_name: input.authorName,
  timestamp: timestamp,
  query_source: input.query_source,

  // Simple success tracking
  has_error: !!input.has_error,
  response_length: input.output.length
};

console.log(`💾 Storing memory: ${intent} query about [${Object.values(entities).flat().join(', ')}]`);

return [{
  json: {
    ...input,
    timestamp: timestamp,
    point_id: $execution.id,
    conversation_text_for_embedding: conversationText,
    essential_memory_payload: essentialPayload
  }
}];

// Prepare Qdrant Payload - Optimized for Google text-embedding-004
const input = $input.first().json;

// Extract the embedding from Google's response structure
// Google returns: { embedding: { values: [array of floats] } }
const embedding = input.embedding?.values;

if (!Array.isArray(embedding) || embedding.length === 0) {
  throw new Error('❌ Invalid embedding received from Google API. Expected structure: embedding.values');
}

console.log(`✅ Received embedding with ${embedding.length} dimensions`);

// Generate a proper UUID for Qdrant (UUID v4 format)
function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}
const pointId = generateUUID();

// Use the enhanced memory payload from the storage preparation
const enhancedPayload = input.essential_memory_payload || {};

// Create the structured Qdrant point object with ENHANCED metadata
const qdrantPoint = {
  id: pointId,
  vector: embedding, // The raw vector array from Google
  payload: {
    // Use your enhanced memory structure
    ...enhancedPayload,

    // Add some core fields for backward compatibility
    text: enhancedPayload.conversation_text, // For text search
    authorId: enhancedPayload.author_id,
    execution_id: input.point_id,
    embedding_model: 'text-embedding-004',
    embedding_dimensions: embedding.length
  }
};

const entityList = Object.values(enhancedPayload.entities || {}).flat().join(', ') || 'none';
console.log(`💾 Storing enhanced memory with intent: ${enhancedPayload.intent}, entities: [${entityList}]`);

// Return the original data plus our new structured object
return [{
  json: {
    ...input,
    qdrant_point: qdrantPoint,
  }
}];

// Help Response Generator - Creates witty Alfred responses for invalid commands
const input = $input.first().json;

// Alfred's rotating witty help responses
const helpResponses = [
  `🎩 **I say, \"!${input.invalid_command}\" isn't in my repertoire!**\n\n**Available Lightning Commands:**\n⚡ \`!price <item>\` - Market prices (e.g., \`!price Venture\`)\n🔍 \`!intel <pilot>\` - Character intel (e.g., \`!intel Lord Alfred\`)\n🗺️ \`!route <from> to <to>\` - Jump routes (e.g., \`!route Jita to Amarr\`)\n🛡️ \`!system <name>\` - System security (e.g., \`!system Jita\`)\n\n*Do try again with something resembling a proper command, if you please.*`,

  `🤔 **Right then... \"!${input.invalid_command}\" is not one of mine.**\n\n**Lightning Commands at your service:**\n⚡ \`!price <item>\` - Market data (e.g., \`!price Venture\`)\n🔍 \`!intel <pilot>\` - Threat assessment (e.g., \`!intel Lord Alfred\`)\n🗺️ \`!route <from> to <to>\` - Travel planning (e.g., \`!route Jita to Amarr\`)\n🛡️ \`!system <name>\` - Security status (e.g., \`!system Jita\`)\n\n*Perhaps consult the manual next time? Oh wait, you're looking at it.*`,

  `⚠️ **I'm terribly sorry, but \"!${input.invalid_command}\" is as useful as a chocolate teapot.**\n\n**What I actually understand:**\n⚡ \`!price <item>\` - Get market prices (e.g., \`!price Venture\`)\n🔍 \`!intel <pilot>\` - Check pilot intel (e.g., \`!intel Lord Alfred\`)\n🗺️ \`!route <from> to <to>\` - Find jump routes (e.g., \`!route Jita to Amarr\`)\n🛡️ \`!system <name>\` - Get system security (e.g., \`!system Jita\`)\n\n*BLOB5 Alliance pilots are usually more... articulate than that.*`,

  `🙄 **Oh, \"!${input.invalid_command}\"... another creative interpretation of my command structure.**\n\n**The actual commands, for those keeping score:**\n⚡ \`!price <item>\` - Item market analysis (e.g., \`!price Venture\`)\n🔍 \`!intel <pilot>\` - Pilot background checks (e.g., \`!intel Lord Alfred\`)\n🗺️ \`!route <from> to <to>\` - Navigation assistance (e.g., \`!route Jita to Amarr\`)\n🛡️ \`!system <name>\` - System security intel (e.g., \`!system Jita\`)\n\n*I suppose I could add mind reading to my skill queue, but the training time is dreadful.*`
];

// Pick a random witty response
const response = helpResponses[Math.floor(Math.random() * helpResponses.length)];

console.log(`🎩 Generated help response for invalid command: !${input.invalid_command}`);

// Create the final output in specialist_data format
const output = {
  // Core message data
  id: input.id,
  content: input.content,
  channelId: input.channelId,
  authorId: input.authorId,
  authorName: input.authorName,
  timestamp: input.timestamp,
  is_dm: input.is_dm,
  query_source: input.query_source,
  type: input.type,

  // Help response data
  specialist_data: {
    response_type: 'invalid_command_help',
    invalid_command: input.invalid_command,
    original_content: input.original_content,
    help_message: response,
    generated_at: new Date().toISOString(),
    has_error: false
  }
};

return [{ json: output }];

// Essential Context Injection - Replace "Inject Historical Memory"
// Creates better context for Alfred without information overload

const inputData = $input.first().json;
// Handle both possible data structures
const searchResults = inputData.body?.result || inputData.result || [];
const searchContext = inputData.search_context || {};

console.log(`📥 Context Injection received ${searchResults.length} search results`);

function buildEssentialContext() {
  if (searchResults.length === 0) {
    return "No relevant conversation history found.";
  }

  const contextSections = [];
  
  // Group memories by type for better organization
  const memories = {
    recent: [],
    entity_related: [],
    same_intent: []
  };
  
  // Categorize memories
  searchResults.forEach(item => {
    const payload = item.payload || {};
    const text = payload.text || payload.conversation_text || '';
    const timestamp = payload.timestamp;
    const intent = payload.intent || 'unknown';
    
    // Recent (last 24 hours)
    if (timestamp) {
      const hoursAgo = (Date.now() - new Date(timestamp).getTime()) / (1000 * 60 * 60);
      if (hoursAgo < 24) {
        memories.recent.push({ text, hoursAgo: Math.round(hoursAgo), intent });
      }
    }
    
    // Entity-related (shares entities with current query)
    const currentEntities = searchContext.entities_found || [];
    const hasSharedEntity = currentEntities.some(entity => 
      text.toLowerCase().includes(entity.toLowerCase())
    );
    if (hasSharedEntity) {
      memories.entity_related.push({ text, intent });
    }
    
    // Same intent as current query
    if (intent === searchContext.current_intent) {
      memories.same_intent.push({ text, intent });
    }
  });
  
  // Build context sections
  
  // 1. Recent conversations (if any)
  if (memories.recent.length > 0) {
    contextSections.push("**Recent discussions:**");
    memories.recent.slice(0, 2).forEach(memory => {
      const timeNote = memory.hoursAgo < 1 ? "just now" : `${memory.hoursAgo}h ago`;
      contextSections.push(`- ${memory.text.substring(0, 100)}... (${timeNote})`);
    });
  }
  
  // 2. Related entities (if different from recent)
  const nonRecentEntityMemories = memories.entity_related.filter(em => 
    !memories.recent.some(rm => rm.text === em.text)
  );
  
  if (nonRecentEntityMemories.length > 0) {
    const entities = searchContext.entities_found?.join(', ') || 'related topics';
    contextSections.push(`**Previous discussions about ${entities}:**`);
    nonRecentEntityMemories.slice(0, 2).forEach(memory => {
      contextSections.push(`- ${memory.text.substring(0, 100)}...`);
    });
  }
  
  // 3. Same type of request (if this seems like a follow-up)
  if (searchContext.is_follow_up && memories.same_intent.length > 0) {
    const intentLabel = searchContext.current_intent || 'similar requests';
    contextSections.push(`**Previous ${intentLabel} queries:**`);
    memories.same_intent.slice(0, 1).forEach(memory => {
      contextSections.push(`- ${memory.text.substring(0, 100)}...`);
    });
  }
  
  // If no specific categories, just show most relevant
  if (contextSections.length === 0) {
    contextSections.push("**Related conversation history:**");
    searchResults.slice(0, 2).forEach(item => {
      const text = item.payload?.text || item.payload?.conversation_text || '';
      if (text) {
        contextSections.push(`- ${text.substring(0, 100)}...`);
      }
    });
  }
  
  return contextSections.join('\n');
}

const conversationContext = buildEssentialContext();

// ------------------- 
// 👈 SECTION MODIFIED
// -------------------
// The 'memoryNote' is excellent for debugging but it breaks the AI's persona
// by explicitly mentioning "memory", "entities", etc.
// We will now only pass the clean conversation context to the AI.
const fullContext = conversationContext;
//
// -------------------
// END OF MODIFICATION
// -------------------


console.log(`📝 Context built: ${conversationContext.length} chars, ${searchResults.length} memories`);

return [{
  json: {
    ...inputData,
    conversation_context: fullContext,
    // This summary is still returned, but it is NOT part of the
    // context string sent to the AI, so he won't see it.
    memory_summary: {
      memories_found: searchResults.length,
      context_type: searchContext.current_intent || 'general',
      is_follow_up: searchContext.is_follow_up || false,
      entities_mentioned: searchContext.entities_found || []
    }
  }
}];

/**
 * Enhanced System & Region Report Generator v4.3
 * Generates context-aware reports for K-Space, W-Space, and Drifter Systems.
 * UPDATED: Moved security class emoji (🟢🟡🔴🟣) next to the System Type label.
 * UPDATED: Added threat level emoji (🔴🟡🟢🚨⚪) next to the "Player Threat" line.
 * UPDATED: Recommended Action is dynamic based on threat level.
 * * Reads from the pre-compiled `templated_response_data` object.
 */

class ReportGenerator {
    constructor() {
        this.colors = { RESET: "\u001b[0m", DIM: "\u001b[2m", BRIGHT: "\u001b[1m", RED: "\u001b[31m", GREEN: "\u001b[32m", YELLOW: "\u001b[33m", CYAN: "\u001b[36m", WHITE: "\u001b[37m", BLUE: "\u001b[34m", MAGENTA: "\u001b[35m" };
        this.styles = { HEADING: this.colors.DIM + this.colors.CYAN, LABEL: this.colors.DIM + this.colors.WHITE, VALUE_GOOD: this.colors.GREEN, VALUE_BAD: this.colors.RED, VALUE_NEUTRAL: this.colors.WHITE, VALUE_HIGHLIGHT: this.colors.YELLOW, VALUE_ISK: this.colors.BRIGHT + this.colors.YELLOW, VALUE_CYAN: this.colors.BRIGHT + this.colors.CYAN, LINE: this.colors.DIM + this.colors.CYAN, WORMHOLE: this.colors.BRIGHT + this.colors.MAGENTA };
    }

    // Gets 🔴🟡🟢🚨⚪ based on threat level string
    getRiskEmoji(threatLevel) {
        switch (threatLevel?.toLowerCase()) {
            case 'extremely high': case 'extreme': return '🚨';
            case 'high': return '🔴';
            case 'moderate': case 'medium': return '🟡';
            case 'low': return '🟢';
            default: return '⚪';
        }
    }

    // Gets 🟢🟡🔴🟣 based on security class string
    getSecurityClassEmoji(securityClass, isWH) {
        if (isWH) return '🟣'; // Purple for Wormhole
        switch (securityClass?.toLowerCase()) {
            case 'highsec': return '🟢'; // Green for High-sec
            case 'lowsec':  return '🟡'; // Yellow for Low-sec
            case 'nullsec': return '🔴'; // Red for Null-sec
            default:        return '⚪'; // White as fallback
        }
    }

    getRecommendedAction(threatLevel) {
        switch (threatLevel?.toLowerCase()) {
            case 'extremely high': case 'extreme': case 'high':
                return `${this.styles.VALUE_BAD}EXTREME CAUTION ADVISED${this.colors.RESET}`;
            case 'moderate': case 'medium':
                return `${this.styles.VALUE_HIGHLIGHT}VIGILANT SCANNING RECOMMENDED${this.colors.RESET}`;
            case 'low':
                return `${this.styles.VALUE_GOOD}STANDARD AWARENESS ADVISED${this.colors.RESET}`;
            default:
                return `${this.styles.VALUE_NEUTRAL}ASSESS LOCAL CONDITIONS${this.colors.RESET}`;
        }
    }

    formatTimestamp(isoString) {
        if (!isoString) return 'N/A';
        const date = new Date(isoString);
        return date.toISOString().replace('T', ' ').substring(0, 16) + ' UTC';
    }

    stripAnsi(str) { return str.replace(/\u001b\[[0-9;]*m/g, ''); }

    padLeft(text, length) {
        const rawText = String(text);
        const strippedLength = this.stripAnsi(rawText).length;
        const ansiLengthDiff = rawText.length - strippedLength;
        return rawText.padStart(length + ansiLengthDiff, ' ');
    }

    isWormholeSystem(snapshotData) {
        const query_name = snapshotData?.query_name || "";
        const security_class = snapshotData?.security_class || "";
        const wh_class_num = snapshotData?.wormhole_class_numeric || 0;
        if (wh_class_num > 0 || security_class === 'wormhole' || /^J\d{6}$/i.test(query_name)) {
            return true;
        }
        return false;
    }

    formatStatics(staticsInput) {
        if (!staticsInput || staticsInput === 'None') return `${this.styles.VALUE_NEUTRAL}None${this.colors.RESET}`;
        if (typeof staticsInput === 'string' && staticsInput.includes('→')) {
            return staticsInput.split(',').map(item => {
                const match = item.trim().match(/^(\w+)\s*\(→\s*(.+)\)$/);
                if (match) { const code = match[1]; const dest = match[2]; return `${this.styles.VALUE_CYAN}${code}${this.colors.RESET} (→ ${this.styles.VALUE_NEUTRAL}${dest}${this.colors.RESET})`; }
                return `${this.styles.VALUE_NEUTRAL}${item.trim()}${this.colors.RESET}`;
            }).join(', ');
        }
        let codes = [];
        if (Array.isArray(staticsInput)) { codes = staticsInput; }
        else if (typeof staticsInput === 'string') { codes = staticsInput.split(',').map(s => s.trim()).filter(s => s); }
        if (codes.length === 0) { return `${this.styles.VALUE_NEUTRAL}None${this.colors.RESET}`; }
        return codes.map(code => `${this.styles.VALUE_CYAN}${code}${this.colors.RESET}`).join(', ');
    }

    generateKSpaceReport(snapshotData) {
        const kills_1h_display = snapshotData.last_hour_ship_kills || 0;
        const kills_24h_display = snapshotData.kills_last_24h || 0;
        const isk_destroyed_1h_display = snapshotData.last_hour_isk_destroyed_formatted || "0 ISK";
        const isk_destroyed_24h_display = snapshotData.value_destroyed_24h_isk_formatted || "0 ISK";
        const jumps_1h_display = snapshotData.last_hour_jumps || 0;
        const npc_kills_1h_display = snapshotData.last_hour_npc_kills || 0;
        const threatLevel = snapshotData.threat_level || 'Unknown';

        const recommendedAction = this.getRecommendedAction(threatLevel);
        // --- GET BOTH EMOJIS ---
        const securityEmoji = this.getSecurityClassEmoji(snapshotData.security_class, false);
        const threatEmoji = this.getRiskEmoji(threatLevel); // Get 🔴🟡🟢 etc.

        const lines = [];

        // --- UPDATED: Prepend Security Emoji to Label ---
        lines.push(`${this.styles.HEADING}${securityEmoji} ${snapshotData.system_type_label}:${this.colors.RESET}${this.styles.VALUE_NEUTRAL} ${snapshotData.query_name.toUpperCase()}${this.colors.RESET}`);

        // --- UPDATED: Simple heading, emoji moved to threat line ---
        lines.push(`\n${this.styles.HEADING}THREAT ASSESSMENT${this.colors.RESET}`);
        lines.push(`${this.styles.LABEL}- Player Threat:${this.colors.RESET} ${threatEmoji} ${this.styles.VALUE_NEUTRAL}${threatLevel.toUpperCase()}${this.colors.RESET}`);
        lines.push(`${this.styles.LABEL}- Recommended Action:${this.colors.RESET} ${recommendedAction}`);

        lines.push(`\n${this.styles.HEADING}STATIC INTEL${this.colors.RESET}`);
        lines.push(`${this.styles.LABEL}- Location:${this.colors.RESET}${this.styles.VALUE_NEUTRAL} ${snapshotData.full_location}${this.colors.RESET}`);
        lines.push(`${this.styles.LABEL}- Stargates:${this.colors.RESET}${this.styles.VALUE_GOOD} ${snapshotData.stargates}${this.colors.RESET}`);
        lines.push(`${this.styles.LABEL}- Stations:${this.colors.RESET}${this.styles.VALUE_GOOD} ${snapshotData.stations}${this.colors.RESET}`);

        lines.push(`\n${this.styles.HEADING}📊 LIVE ACTIVITY${this.colors.RESET}`);
        lines.push(`${this.styles.LINE}-------------------+-----------+-----------${this.colors.RESET}`);
        lines.push(`${this.styles.LABEL}Metric             \u001b[2m\u001b[36m| 1h         | 24h       \u001b[0m`);
        lines.push(`${this.styles.LINE}-------------------+-----------+-----------${this.colors.RESET}`);

        lines.push(`${this.styles.LABEL}💥 Ship Kills      \u001b[0m| ${this.styles.VALUE_BAD}${this.padLeft(String(kills_1h_display), 9)}${this.colors.RESET} | ${this.styles.VALUE_BAD}${this.padLeft(String(kills_24h_display), 9)}${this.colors.RESET}`);
        lines.push(`${this.styles.LABEL}💸 ISK Destroyed   \u001b[0m| ${this.styles.VALUE_BAD}${this.padLeft(String(isk_destroyed_1h_display.replace(' ISK', '')), 9)}${this.colors.RESET} | ${this.styles.VALUE_BAD}${this.padLeft(String(isk_destroyed_24h_display.replace(' ISK', '')), 9)}${this.colors.RESET}`);

        lines.push(`\n${this.styles.LABEL}🚀 Jumps (Last Hour):${this.colors.RESET}${this.styles.VALUE_HIGHLIGHT} ${jumps_1h_display.toLocaleString()}${this.colors.RESET}`);
        lines.push(`${this.styles.LABEL}👾 NPC Kills (Last Hour):${this.colors.RESET}${this.styles.VALUE_GOOD} ${npc_kills_1h_display.toLocaleString()}${this.colors.RESET}`);

        lines.push(`\n${this.styles.HEADING}⭐ TOP INTEL (24H)${this.colors.RESET}`);
        const mvKSummary = snapshotData.most_valuable_kill_24h_summary || 'None';
        const mvKRegex = /(.*) \(([0-9.]+[TMKB] ISK)\) by (.*)/;
        const mvKMatch = mvKSummary.match(mvKRegex);
        if (mvKMatch) { lines.push(`${this.styles.LABEL}- Most Valuable Kill: ${this.colors.RESET}${this.styles.VALUE_NEUTRAL}${mvKMatch[1]}${this.colors.RESET} (${this.styles.VALUE_ISK}${mvKMatch[2]}${this.colors.RESET}) by ${this.styles.VALUE_NEUTRAL}${mvKMatch[3]}${this.colors.RESET}`); }
        else { lines.push(`${this.styles.LABEL}- Most Valuable Kill: ${this.colors.RESET}${this.styles.VALUE_NEUTRAL}${mvKSummary}${this.colors.RESET}`); }

        const parseListWithCounts = (listString) => {
            return (listString || 'None').split(', ').map(item => {
                const match = item.match(/(.+) \((\d+)\)/);
                if (match) { return `${this.styles.VALUE_NEUTRAL}${match[1]}${this.colors.RESET} (${this.styles.VALUE_CYAN}${match[2]}${this.colors.RESET})`; }
                return `${this.styles.VALUE_NEUTRAL}${item}${this.colors.RESET}`;
            }).join(', ');
        };

        lines.push(`${this.styles.LABEL}- Top Hunters: ${this.colors.RESET}${parseListWithCounts(snapshotData.top_hunters_24h_list)}`);
        lines.push(`${this.styles.LABEL}- Top Victims: ${this.colors.RESET}${parseListWithCounts(snapshotData.top_victims_24h_list)}`);

        return lines;
    }

    generateWSpaceReport(snapshotData, fullData) {
        const threatLevel = snapshotData.threat_level || 'Unknown';
        const recommendedAction = this.getRecommendedAction(threatLevel);
        // --- GET BOTH EMOJIS ---
        const securityEmoji = this.getSecurityClassEmoji(snapshotData.security_class, true); // True for WH = 🟣
        const threatEmoji = this.getRiskEmoji(threatLevel);

        const lines = [];

        // --- UPDATED: Prepend Security Emoji to Label ---
        lines.push(`${this.styles.WORMHOLE}${securityEmoji} ${snapshotData.system_type_label}:${this.colors.RESET}${this.styles.VALUE_NEUTRAL} ${snapshotData.query_name.toUpperCase()}${this.colors.RESET}`);

        // --- UPDATED: Simple heading, emoji moved to threat line ---
        lines.push(`\n${this.styles.HEADING}THREAT ASSESSMENT${this.colors.RESET}`);
        lines.push(`${this.styles.LABEL}- Player Threat:${this.colors.RESET} ${threatEmoji} ${this.styles.VALUE_NEUTRAL}${threatLevel.toUpperCase()}${this.colors.RESET}`);

        let staticThreatNPC = snapshotData.static_threat_npc ? snapshotData.static_threat_npc.toUpperCase() : 'UNKNOWN';
        let staticThreatColor = this.styles.VALUE_BAD;
        if (staticThreatNPC.includes('NONE')) { staticThreatColor = this.styles.VALUE_NEUTRAL; }
        else if (staticThreatNPC.includes('DRIFTER')) { staticThreatColor = this.colors.MAGENTA; }

        lines.push(`${this.styles.LABEL}- Static Threat:${this.colors.RESET}${staticThreatColor} ${staticThreatNPC}${this.colors.RESET}`);
        lines.push(`${this.styles.LABEL}- Recommended Action:${this.colors.RESET} ${recommendedAction}`);

        lines.push(`\n${this.styles.HEADING}STATIC INTEL${this.colors.RESET}`);
        lines.push(`${this.styles.LABEL}- Location:${this.colors.RESET}${this.styles.VALUE_NEUTRAL} ${snapshotData.full_location}${this.colors.RESET}`);
        lines.push(`${this.styles.LABEL}- Class:${this.colors.RESET}${this.styles.WORMHOLE} ${snapshotData.wormhole_class}${this.colors.RESET}`);

        const whEffect = snapshotData.wormhole_effects || 'None';
        if (whEffect && whEffect !== 'None' && whEffect !== 'N/A') {
            lines.push(`${this.styles.LABEL}- Effect:${this.colors.RESET}${this.styles.VALUE_HIGHLIGHT} ${whEffect}${this.colors.RESET}`);
        }

        const formattedStatics = this.formatStatics(snapshotData.wormhole_statics_list);
        lines.push(`${this.styles.LABEL}- Statics: ${this.colors.RESET}${formattedStatics}`);

        const connections = fullData.pathfinder_intel?.connections;
        lines.push(`\n${this.styles.HEADING}🔗 ACTIVE CONNECTIONS (via Pathfinder)${this.colors.RESET}`);
        if (connections && connections.length > 0) {
            connections.forEach(conn => {
                const eol = conn.eol ? ` ${this.styles.VALUE_BAD}(EOL)${this.colors.RESET}` : '';
                const mass = conn.mass_status === 'critical' ? ` ${this.styles.VALUE_BAD}(Crit Mass)${this.colors.RESET}` : '';
                const time = conn.time_status === 'critical' ? ` ${this.styles.VALUE_BAD}(Crit Time)${this.colors.RESET}` : '';
                lines.push(`${this.styles.LABEL}- ${this.styles.VALUE_NEUTRAL}${conn.destination} (${conn.destination_class})${this.colors.RESET}${eol}${mass}${time}`);
            });
        } else {
            lines.push(`${this.styles.LABEL}- No active K-space connections detected.${this.colors.RESET}`);
        }

        const kills_1h_display = snapshotData.last_hour_ship_kills || 0;
        const kills_24h_display = snapshotData.kills_last_24h || 0;
        const isk_destroyed_1h_display = snapshotData.last_hour_isk_destroyed_formatted || "0 ISK";
        const isk_destroyed_24h_display = snapshotData.value_destroyed_24h_isk_formatted || "0 ISK";

        lines.push(`\n${this.styles.HEADING}📊 RECENT PLAYER ACTIVITY${this.colors.RESET}`);
        lines.push(`${this.styles.LINE}-------------------+-----------+-----------${this.colors.RESET}`);
        lines.push(`${this.styles.LABEL}Metric             \u001b[2m\u001b[36m| 1h         | 24h       \u001b[0m`);
        lines.push(`${this.styles.LINE}-------------------+-----------+-----------${this.colors.RESET}`);
        lines.push(`${this.styles.LABEL}🚢 Ship Kills      \u001b[0m| ${this.styles.VALUE_BAD}${this.padLeft(String(kills_1h_display), 9)}${this.colors.RESET} | ${this.styles.VALUE_BAD}${this.padLeft(String(kills_24h_display), 9)}${this.colors.RESET}`);
        lines.push(`${this.styles.LABEL}💸 ISK Destroyed   \u001b[0m| ${this.styles.VALUE_BAD}${this.padLeft(isk_destroyed_1h_display.replace(' ISK', ''), 9)}${this.colors.RESET} | ${this.styles.VALUE_BAD}${this.padLeft(isk_destroyed_24h_display.replace(' ISK', ''), 9)}${this.colors.RESET}`);

        return lines;
    }

    generate(data) {
        const snapshotData = data.templated_response_data;
        if (!snapshotData || !snapshotData.type) {
             if (data.query_type) { return `❌ **Error**: Report data is missing. The 'templated_response_data' object could not be found.`; }
             return `❌ **Error**: Final snapshot data is missing or invalid.`;
        }

        const lines = ['```ansi'];

        if (snapshotData.type === 'system_snapshot') {
            if (this.isWormholeSystem(snapshotData)) {
                lines.push(...this.generateWSpaceReport(snapshotData, data));
            } else {
                lines.push(...this.generateKSpaceReport(snapshotData));
            }
        } else if (snapshotData.type === 'region_snapshot') {
             const threatEmoji = this.getRiskEmoji(snapshotData.threat_level); // Use risk emoji for threat
             // No single security class for a region, maybe use a generic icon like 🗺️ or skip it
             lines.push(`${this.styles.HEADING}🗺️ REGION SNAPSHOT:${this.colors.RESET}${this.styles.VALUE_NEUTRAL} ${snapshotData.query_name.toUpperCase()}${this.colors.RESET}`);
             lines.push(`${this.styles.HEADING}THREAT LEVEL:${this.colors.RESET}${this.styles.VALUE_NEUTRAL} ${threatEmoji} ${snapshotData.threat_level ? snapshotData.threat_level.toUpperCase() : 'UNKNOWN'}${this.colors.RESET}`);
             // ... other region stats ...
        } else {
             lines.push(`❌ **Error**: Unknown snapshot_type: ${snapshotData.type}`);
        }

        lines.push(`\n${this.styles.LABEL}Generated by Alfred: ${this.colors.RESET}${this.styles.HEADING}${this.formatTimestamp(data.metadata?.generated_at)}${this.colors.RESET}`);
        lines.push('```');

        return lines.join('\n');
    }
}

