/**
 * Standalone Route Report Generator v1.5 (Corrected)
 * Takes the final data object from the !route workflow and generates the full ANSI response.
 * Focuses on 1-hour intel for tactical relevance, with 24-hour data for context.
 */

class ReportGenerator {
    constructor() {
        // ANSI Color codes
        this.colors = { RESET: "\u001b[0m", DIM: "\u001b[2m", BRIGHT: "\u001b[1m", RED: "\u001b[31m", GREEN: "\u001b[32m", YELLOW: "\u001b[33m", CYAN: "\u001b[36m", WHITE: "\u001b[37m" };
        this.styles = { HEADING: this.colors.DIM + this.colors.CYAN, LABEL: this.colors.DIM + this.colors.WHITE, VALUE_GOOD: this.colors.GREEN, VALUE_BAD: this.colors.RED, VALUE_NEUTRAL: this.colors.WHITE, VALUE_HIGHLIGHT: this.colors.YELLOW, VALUE_ISK: this.colors.BRIGHT + this.colors.YELLOW, VALUE_CYAN: this.colors.BRIGHT + this.colors.CYAN, LINE: this.colors.DIM + this.colors.CYAN };
    }

    // --- UTILITY FUNCTIONS ---
    formatISK(amount, includeISK = true) { if (amount === null || amount === undefined || isNaN(parseFloat(amount))) return '0'; const num = parseFloat(String(amount).replace(/,/g, '')); let suffix = ''; let val = num; if (num >= 1e12) { val = num / 1e12; suffix = 'T'; } else if (num >= 1e9) { val = num / 1e9; suffix = 'B'; } else if (num >= 1e6) { val = num / 1e6; suffix = 'M'; } else if (num >= 1000) { val = num / 1000; suffix = 'K'; } let formattedVal; if (suffix) { formattedVal = val % 1 === 0 ? `${val.toFixed(0)}` : `${val.toFixed(1)}`; } else { formattedVal = `${val.toLocaleString(undefined, {minimumFractionDigits: 0, maximumFractionDigits: 0})}`; } return `${formattedVal}${suffix}${includeISK ? ' ISK' : ''}`; }
    getRiskEmoji(threatLevel) { switch (threatLevel?.toLowerCase()) { case 'extremely high': case 'extreme': return '🚨'; case 'high': return '🔴'; case 'moderate': case 'medium': return '🟡'; case 'low': return '🟢'; case 'frequent target': return '🎯'; default: return '⚪'; } }
    getValueEmoji(value) { if (value >= 1e10) return '💎'; if (value >= 1e9) return '💰'; if (value >= 1e8) return '⚡'; if (value >= 1e7) return '🔥'; if (value >= 1e6) return '💥'; return '🎯'; }
    getTimeAgo(isoTime) { if (!isoTime) return 'unknown time'; const now = new Date(); const past = new Date(isoTime); const diffMs = now - past; const diffMins = Math.floor(diffMs / 60000); const diffHours = Math.floor(diffMins / 60); const diffDays = Math.floor(diffHours / 24); if (diffMins < 1) return 'now'; if (diffMins < 60) return `${diffMins}m ago`; if (diffHours < 24) return `${diffHours}h ago`; return `${diffDays}d ago`; }
    formatTimestamp(isoString) { if (!isoString) return 'N/A'; const date = new Date(isoString); const year = date.getUTCFullYear(); const month = (date.getUTCMonth() + 1).toString().padStart(2, '0'); const day = date.getUTCDate().toString().padStart(2, '0'); const hours = date.getUTCHours().toString().padStart(2, '0'); const minutes = date.getUTCMinutes().toString().padStart(2, '0'); return `${year}-${month}-${day} ${hours}:${minutes} UTC`; }

    // --- MAIN TEMPLATE GENERATION ---
    generate(specialistData) {
        const lines = [];
        const routeData = specialistData.route || specialistData.route_data || specialistData;
        const origin = routeData.origin || routeData.origin_system || routeData.from_system;
        const destination = routeData.destination || routeData.destination_system || routeData.to_system;

        if (!origin || !destination) {
            return '❌ **Route Error** - Could not calculate route. Please check system names.';
        }

        const now = new Date();
        const oneHourAgo = new Date(now.getTime() - 60 * 60 * 1000);
        // const twentyFourHoursAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000); // No longer needed

        lines.push('```ansi');
        const origin_name = String(origin).toUpperCase();
        const destination_name = String(destination).toUpperCase();
        const totalJumps = routeData.total_jumps || (specialistData.systems ? specialistData.systems.length : 0);
        const threatLevel = specialistData.threat_assessment?.level || 'Unknown';
        const riskEmoji = this.getRiskEmoji(threatLevel);
        const etaSeconds = totalJumps * 45;
        const etaMinutes = Math.floor(etaSeconds / 60);
        const etaString = `${etaMinutes}m ${etaSeconds % 60}s`;
        const characteristics = specialistData.route_characteristics || {};
        const secBreakdown = characteristics.security_breakdown || {};
        const secParts = [secBreakdown.highsec ? `${secBreakdown.highsec}H` : null, secBreakdown.lowsec ? `${secBreakdown.lowsec}L` : null, secBreakdown.nullsec ? `${secBreakdown.nullsec}N` : null].filter(p => p).join('-');

        lines.push(`${this.styles.HEADING}🗺️ ${origin_name} → ${destination_name}${this.colors.RESET} | ${riskEmoji} ${threatLevel.toUpperCase()}`);
        lines.push(`${this.styles.LABEL}${totalJumps} jumps (${etaString}) | Security: ${secParts || 'Unknown'}${this.colors.RESET}`);

        const systems = specialistData.systems || [];
        systems.forEach((sys, index) => {
            const jumpNum = (index + 1).toString().padStart(2, ' ');
            const secClass = sys.security_class === 'highsec' ? '🟢' : sys.security_class === 'lowsec' ? '🟡' : '🔴';
            const secStatus = sys.security_status ? sys.security_status.toFixed(1) : 'N/A';
            const intel = sys.live_intel || {};
            const tags = [];
            if (sys.is_gank_hotspot) tags.push('🎯');
            if (sys.is_chokepoint) tags.push('🔒');
            if (sys.is_trade_hub) tags.push('🏪');

            const killsLastHour = (intel.recent_kills_sample || []).filter(k => new Date(k.time) >= oneHourAgo).length;
            if (killsLastHour > 0) tags.push(`💥${killsLastHour}`);
            const tagStr = tags.length > 0 ? ` ${tags.join(' ')}` : '';
            lines.push(`${this.styles.LABEL}${jumpNum}. ${this.colors.RESET}${secClass}${secStatus} ${this.styles.VALUE_NEUTRAL}${sys.name}${tagStr}${this.colors.RESET}`);
        });

        lines.push('');
        lines.push(`${this.styles.HEADING}📊 ROUTE INTEL (Last Hour)${this.colors.RESET}`);

        // --- FIX 1: Use pre-calculated totals from summary, but calculate 1h total ---
        const summary = specialistData.live_intel_summary || {};
        let totalKills1h = 0, totalValue1h = 0;

        // 1-hour totals are NOT in the summary, so we must calculate them.
        // We use "kill.val" here, which is correct for the "systems" array.
        systems.forEach(sys => {
            const intel = sys.live_intel || {};
            const killsSample = intel.recent_kills_sample || [];
            killsSample.forEach(kill => {
                if (new Date(kill.time) >= oneHourAgo) {
                    totalKills1h++;
                    totalValue1h += kill.val || 0;
                }
            });
        });

        // 24-hour totals ARE in the summary, so we just read them.
        const totalKills24h = summary.activity_summary?.total_kills || 0;
        const totalValue24h = summary.activity_summary?.total_value_destroyed || 0;
        // --- END FIX 1 ---

        if (totalKills1h > 0) {
            lines.push(`${this.styles.LABEL}Kills: ${this.colors.RESET}${this.styles.VALUE_BAD}${totalKills1h}${this.colors.RESET} | ${this.styles.LABEL}Value Lost: ${this.colors.RESET}${this.styles.VALUE_ISK}${this.formatISK(totalValue1h, true)}${this.colors.RESET}`);
        } else {
            lines.push(`${this.styles.LABEL}No hostile activity detected in the last hour.${this.colors.RESET}`);
        }

        lines.push('');
        lines.push(`${this.styles.HEADING}📈 24-HOUR CONTEXT${this.colors.RESET}`);
        lines.push(`${this.styles.LABEL}Total Kills: ${this.colors.RESET}${this.styles.VALUE_NEUTRAL}${totalKills24h}${this.colors.RESET} | ${this.styles.LABEL}Total Value Lost: ${this.colors.RESET}${this.styles.VALUE_NEUTRAL}${this.formatISK(totalValue24h, true)}${this.colors.RESET}`);


        const liveIntelSummary = specialistData.live_intel_summary;
        if (liveIntelSummary?.recent_activity?.length > 0) {
            lines.push('');
            lines.push(`${this.styles.HEADING}🔥 MOST RECENT ACTIVITY${this.colors.RESET}`);
            const recentKills = liveIntelSummary.recent_activity.slice(0, 3);
            recentKills.forEach(kill => {
                const timeAgo = this.getTimeAgo(kill.time);
                // --- FIX 2: Use kill.value instead of kill.val ---
                const valueEmoji = this.getValueEmoji(kill.value);
                const shipName = kill.victim_ship || 'Unknown Ship';
                const killer = kill.killer || 'Unknown';
                lines.push(`${this.styles.LABEL}${valueEmoji} ${this.colors.RESET}${this.styles.VALUE_NEUTRAL}${shipName}${this.colors.RESET} in ${this.styles.VALUE_HIGHLIGHT}${kill.system_name}${this.colors.RESET} by ${killer} (${this.styles.VALUE_ISK}${this.formatISK(kill.value, true)}${this.colors.RESET}) ${timeAgo}`);
                // --- END FIX 2 ---
            });
        }

        const warnings = [];
        if (characteristics.has_low_sec) warnings.push('Low-sec');
        if (characteristics.has_null_sec) warnings.push('Null-sec');
        if (characteristics.chokepoint_count > 0) warnings.push(`${characteristics.chokepoint_count} chokepoints`);
        if (characteristics.gank_hotspot_count > 0) warnings.push(`${characteristics.gank_hotspot_count} gank zones`);

        if (warnings.length > 0) {
            lines.push('');
            lines.push(`${this.styles.HEADING}⚠️ ROUTE NOTES${this.colors.RESET}`);
            lines.push(`${this.styles.LABEL}${warnings.join(' • ')}${this.colors.RESET}`);
        }

        lines.push('');
        lines.push(`${this.styles.LABEL}Generated by Alfred: ${this.colors.RESET}${this.styles.HEADING}${this.formatTimestamp(new Date().toISOString())}${this.colors.RESET}`);
        lines.push('```');
        return lines.join('\n');
    }
}

