/**
 * Price Report Generator v2.2
 * Generates formatted market analysis reports with ANSI styling
 * 
 * Features:
 * - Current market data (best buy/sell prices with locations)
 * - Arbitrage opportunity detection
 * - 7-day historical trends and volatility
 * - Data freshness indicators
 */

class ReportGenerator {
    constructor() {
        this.colors = { 
            RESET: "\u001b[0m", DIM: "\u001b[2m", BRIGHT: "\u001b[1m", 
            RED: "\u001b[31m", GREEN: "\u001b[32m", YELLOW: "\u001b[33m", 
            CYAN: "\u001b[36m", WHITE: "\u001b[37m", BLUE: "\u001b[34m", 
            MAGENTA: "\u001b[35m" 
        };
        this.styles = { 
            HEADING: this.colors.DIM + this.colors.CYAN, 
            LABEL: this.colors.DIM + this.colors.WHITE, 
            VALUE_GOOD: this.colors.GREEN, 
            VALUE_BAD: this.colors.RED, 
            VALUE_NEUTRAL: this.colors.WHITE, 
            VALUE_HIGHLIGHT: this.colors.YELLOW, 
            VALUE_ISK: this.colors.BRIGHT + this.colors.YELLOW, 
            VALUE_CYAN: this.colors.BRIGHT + this.colors.CYAN, 
            LINE: this.colors.DIM + this.colors.CYAN, 
            DIM: this.colors.DIM 
        };
    }

    formatTimestamp(ts) { 
        if (!ts) ts = new Date().toISOString();
        const date = new Date(ts); 
        const year = date.getUTCFullYear(); 
        const month = (date.getUTCMonth() + 1).toString().padStart(2, '0'); 
        const day = date.getUTCDate().toString().padStart(2, '0'); 
        const hours = date.getUTCHours().toString().padStart(2, '0'); 
        const minutes = date.getUTCMinutes().toString().padStart(2, '0'); 
        return `${year}-${month}-${day} ${hours}:${minutes} UTC`; 
    }

    formatISK(amount) {
        if (typeof amount !== 'number' || isNaN(amount)) return 'N/A';
        return amount.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    }

    getTimeAgo(isoString) {
        if (!isoString) return 'unknown';
        const now = new Date();
        const past = new Date(isoString);
        const diffMs = now - past;
        const diffMins = Math.floor(diffMs / 60000);
        const diffHours = Math.floor(diffMins / 60);

        if (diffMins < 60) return `${diffMins}m ago`;
        if (diffHours < 24) return `${diffHours}h ago`;
        return `${Math.floor(diffHours / 24)}d ago`;
    }

    generate(data) {
        const lines = ['```ansi'];
        lines.push(`\n${this.styles.HEADING}📈 EVE MARKET REPORT${this.colors.RESET}`);

        lines.push(`\n${this.styles.HEADING}🗺️ REGION:${this.colors.RESET}${this.styles.VALUE_HIGHLIGHT} ${data.region.toUpperCase()}${this.colors.RESET}`);
        lines.push(`${this.styles.LINE}-----------------------------------------------------${this.colors.RESET}`);
        lines.push(`${this.styles.VALUE_CYAN}📦 ${data.item_name}${this.colors.RESET}\n`);

        const market = data.market_summary;
        lines.push(`${this.styles.HEADING}🛒 CURRENT MARKET${this.colors.RESET}`);
        if (market) {
            const sellPrice = this.formatISK(market.sell_price);
            const buyPrice = this.formatISK(market.buy_price);
            const spreadISK = this.formatISK(market.spread_isk);
            const spreadPct = market.spread_percent ? market.spread_percent.toFixed(2) : 'N/A';

            const sellLocation = data.market_locations?.best_sell_location || 'Unknown';
            const buyLocation = data.market_locations?.best_buy_location || 'Unknown';

            lines.push(`${this.styles.LABEL}  - 💰 Sell At: ${this.colors.RESET}${this.styles.VALUE_ISK}${sellPrice} ISK${this.colors.RESET}`);
            lines.push(`${this.styles.DIM}    (${sellLocation})${this.colors.RESET}`);

            lines.push(`${this.styles.LABEL}  - 💸 Buy At:  ${this.colors.RESET}${this.styles.VALUE_ISK}${buyPrice} ISK${this.colors.RESET}`);
            lines.push(`${this.styles.DIM}    (${buyLocation})${this.colors.RESET}`);

            lines.push(`${this.styles.LABEL}  - ↔️ Spread:  ${this.colors.RESET}${this.styles.VALUE_NEUTRAL}${spreadISK} ISK${this.colors.RESET} (${this.styles.VALUE_HIGHLIGHT}${spreadPct}%${this.colors.RESET})`);
        } else {
            lines.push(`${this.styles.DIM}  - No order data available.${this.colors.RESET}`);
        }

        lines.push(`\n${this.styles.HEADING}💡 MARKET INSIGHT${this.colors.RESET}`);
        if (market) {
            if (market.spread_isk < 0) {
                const profit = this.formatISK(market.spread_isk * -1);
                lines.push(`${this.styles.VALUE_GOOD}  - ⚡ ARBITRAGE ALERT!${this.colors.RESET}`);
                lines.push(`${this.styles.VALUE_GOOD}    Buy for ${this.formatISK(market.sell_price)} & sell for ${this.formatISK(market.buy_price)} (Profit: ${profit} ISK)${this.colors.RESET}`);
            } else {
                lines.push(`${this.styles.DIM}  - No immediate arbitrage opportunity.${this.colors.RESET}`);
            }

            const sells = market.sell_orders_count || 0;
            const buys = market.buy_orders_count || 0;
            lines.push(`${this.styles.LABEL}  - 📋 Order Book: ${this.colors.RESET}${this.styles.VALUE_NEUTRAL}${sells} Sell Orders / ${buys} Buy Orders${this.colors.RESET}`);
        } else {
            lines.push(`${this.styles.DIM}  - No insights available.${this.colors.RESET}`);
        }

        lines.push(`\n${this.styles.HEADING}📊 7-DAY TRENDS${this.colors.RESET}`);
        const trends = data.market_trends;
        if (trends) {
            const avgPrice = this.formatISK(trends.avg_price_7d);
            const avgVol = trends.avg_daily_volume ? Math.round(trends.avg_daily_volume).toLocaleString() : 'N/A';
            const volatility = trends.volatility_percent ? trends.volatility_percent.toFixed(2) : 'N/A';
            const priceChange = trends.price_change_percent ? trends.price_change_percent.toFixed(2) : 'N/A';

            let trendEmoji = '➖';
            if (trends.price_change_percent > 0) trendEmoji = '📈';
            if (trends.price_change_percent < 0) trendEmoji = '📉';

            lines.push(`${this.styles.LABEL}  - ⚖️ Avg Price: ${this.colors.RESET}${this.styles.VALUE_NEUTRAL}${avgPrice} ISK${this.colors.RESET}`);
            lines.push(`${this.styles.LABEL}  - 🚛 Avg Volume: ${this.colors.RESET}${this.styles.VALUE_NEUTRAL}${avgVol} units/day${this.colors.RESET}`);
            lines.push(`${this.styles.LABEL}  - ${trendEmoji} Price Change: ${this.colors.RESET}${this.styles.VALUE_NEUTRAL}${priceChange}%${this.colors.RESET}`);
            lines.push(`${this.styles.LABEL}  - 🌊 Volatility: ${this.colors.RESET}${this.styles.VALUE_NEUTRAL}${volatility}%${this.colors.RESET}`);
        } else {
            lines.push(`${this.styles.DIM}  - No history data available.${this.colors.RESET}`);
        }

        lines.push(`\n${this.styles.LINE}-----------------------------------------------------${this.colors.RESET}`);

        const freshness = data.data_freshness;
        if (freshness?.market_last_update) {
            const marketAge = this.getTimeAgo(freshness.market_last_update);
            lines.push(`${this.styles.LABEL}📊 Market Data: ${this.colors.RESET}${this.styles.DIM}${marketAge}${this.colors.RESET}`);
        }

        lines.push(`${this.styles.LABEL}🤖 Generated by Alfred: ${this.colors.RESET}${this.styles.HEADING}${this.formatTimestamp(data.timestamp)}${this.colors.RESET}`);
        lines.push('```');
        return lines.join('\n');
    }

    generateError(errorMessage) {
        const lines = ['```ansi'];
        lines.push(`\n${this.styles.HEADING}❌ MARKET REPORT FAILED${this.colors.RESET}`);
        lines.push(``);
        lines.push(`${this.styles.VALUE_BAD}${errorMessage}${this.colors.RESET}`);
        lines.push(``);
        lines.push(`${this.styles.LABEL}🤖 Generated by Alfred: ${this.colors.RESET}${this.styles.HEADING}${this.formatTimestamp(new Date().toISOString())}${this.colors.RESET}`);
        lines.push('```');
        return lines.join('\n');
    }
}

const generator = new ReportGenerator();
const inputJson = $input.first().json;
let finalOutput = '';

try {
    if (inputJson.status === 'success') {
        finalOutput = generator.generate(inputJson);
    } else {
        const errorMsg = inputJson.error || "An unknown error occurred.";
        finalOutput = generator.generateError(errorMsg);
    }

    return [{ json: { ...inputJson, output: finalOutput } }];

} catch (error) {
    console.error('❌ Report formatting failed:', error.message, error.stack);
    const errorOutput = generator.generateError(error.message);
    return [{ 
        json: { 
            ...inputJson, 
            status: 'error', 
            error: `Formatter Failed: ${error.message}`, 
            output: errorOutput 
        } 
    }];
}

/**
 * Character Report Generator v4.7 (Alfred's Upgrade)
 * - FIX: `charId` now correctly reads from the root `character_id`
 * - This version reads from the v4.3 Assembly node.
 * - Reads `stats` (from zKill/local) for LIFETIME sections.
 * - Reads `recent_killmails` (from zKill/local) for RECENT activity.
 * - Reads `analysis` for threat assessment.
 */

class ReportGenerator {
    constructor() {
        this.colors = { 
            RESET: "\x1b[0m", DIM: "\x1b[2m", BRIGHT: "\x1b[1m", 
            RED: "\x1b[31m", GREEN: "\x1b[32m", YELLOW: "\x1b[33m", 
            CYAN: "\x1b[36m", WHITE: "\x1b[37m", BLUE: "\x1b[34m", 
            MAGENTA: "\x1b[35m" 
        };

        this.styles = { 
            HEADING: this.colors.DIM + this.colors.CYAN, 
            LABEL: this.colors.DIM + this.colors.WHITE, 
            VALUE_GOOD: this.colors.GREEN, 
            VALUE_BAD: this.colors.RED, 
            VALUE_NEUTRAL: this.colors.WHITE, 
            VALUE_HIGHLIGHT: this.colors.YELLOW, 
            VALUE_ISK: this.colors.BRIGHT + this.colors.YELLOW, 
            VALUE_CYAN: this.colors.BRIGHT + this.colors.CYAN, 
            LINE: this.colors.DIM + this.colors.CYAN, 
            WORMHOLE: this.colors.BRIGHT + this.colors.MAGENTA, 
            DIM: this.colors.DIM 
        };

        this.GROUP_MAP = {
            25: 'Frigate', 324: 'Assault Frig', 830: 'E-War Frig', 541: 'CovOps Frig', 1527: 'Logi Frig',
            420: 'Destroyer', 540: 'IntyDest', 380: 'ComDest', 1534: 'TacDest',
            26: 'Cruiser', 358: 'HAC', 831: 'E-War Cruiser', 893: 'Logi Cruiser', 237: 'T3 Cruiser',
            419: 'Battlecruiser', 543: 'ComBC',
            27: 'Battleship', 900: 'Black Ops', 1538: 'Marauder',
            30: 'Capital', 547: 'Carrier', 659: 'Titan', 485: 'Dreadnought', 883: 'Supercarrier',
            902: 'Freighter', 941: 'Capital Indy', 29: 'Indy', 28: 'Indy Command'
        };
    }

    formatISK(amount, includeISK = true) { 
        if (amount === null || amount === undefined || isNaN(parseFloat(amount))) return '0'; 
        const num = parseFloat(String(amount).replace(/,/g, '')); 
        let suffix = '', val = num;
        if (num >= 1e12) { val = num / 1e12; suffix = 'T'; } 
        else if (num >= 1e9) { val = num / 1e9; suffix = 'B'; } 
        else if (num >= 1e6) { val = num / 1e6; suffix = 'M'; } 
        else if (num >= 1000) { val = num / 1000; suffix = 'K'; }
        const formattedVal = suffix ? (val % 1 === 0 ? val.toFixed(0) : val.toFixed(1)) : val.toLocaleString(undefined, {minimumFractionDigits: 0, maximumFractionDigits: 0});
        return `${formattedVal}${suffix}${includeISK ? ' ISK' : ''}`;
    }

    getRiskEmoji(threatLevel) { 
        switch (threatLevel?.toLowerCase()) { 
            case 'critical': return '🚨'; 
            case 'high': return '🔴'; 
            case 'medium': return '🟡'; 
            case 'low': return '🟢'; 
            case 'very low': return '⚪'; 
            default: return '⚪'; 
        } 
    }

    getSecStatusEmoji(status) { 
        if (status >= 5.0) return '🔵'; 
        if (status >= 0.0) return '🟢'; 
        if (status >= -2.0) return '🟡'; 
        if (status < -2.0) return '🔴'; 
        return '⚪'; 
    }

    getStandingsStyle(allianceId) {
        const YOUR_ALLIANCE_ID = 99013284; // BLOB5 Alliance ID
        if (!allianceId) {
            return this.styles.VALUE_NEUTRAL + 'NEUTRAL ⚪' + this.colors.RESET;
        }
        if (allianceId === YOUR_ALLIANCE_ID) {
            return this.styles.VALUE_CYAN + 'FRIENDLY 🔷' + this.colors.RESET;
        }
        return this.styles.VALUE_HIGHLIGHT + 'OTHER ⚪' + this.colors.RESET;
    }

    formatTimestamp(isoString) { 
        if (!isoString) return 'N/A'; 
        const date = new Date(isoString); 
        const year = date.getUTCFullYear(); 
        const month = (date.getUTCMonth() + 1).toString().padStart(2, '0'); 
        const day = date.getUTCDate().toString().padStart(2, '0'); 
        const hours = date.getUTCHours().toString().padStart(2, '0'); 
        const minutes = date.getUTCMinutes().toString().padStart(2, '0'); 
        return `${year}-${month}-${day} ${hours}:${minutes} UTC`; 
    }

    formatTimeAgo(isoString) {
        if (!isoString) return 'N/A';
        const now = new Date();
        const past = new Date(isoString);
        const diffInSeconds = Math.floor((now - past) / 1000);
        if (isNaN(diffInSeconds)) return 'N/A';
        if (diffInSeconds < 60) return 'now';
        const diffInMinutes = Math.floor(diffInSeconds / 60);
        if (diffInMinutes < 60) return `${diffInMinutes}m ago`;
        const diffInHours = Math.floor(diffInMinutes / 60);
        if (diffInHours < 24) return `${diffInHours}h ago`;
        const diffInDays = Math.floor(diffInHours / 24);
        if (diffInDays < 30) return `${diffInDays}d ago`;
        const diffInMonths = Math.floor(diffInDays / 30.44);
        if (diffInMonths < 12) return `${diffInMonths}mo ago`;
        const diffInYears = Math.floor(diffInDays / 365.25);
        return `${diffInYears}y ago`;
    }

    formatCharacterAge(creationDateISO) { 
        if (!creationDateISO) return 'Unknown'; 
        const creation = new Date(creationDateISO); 
        const now = new Date(); 
        let months = (now.getFullYear() - creation.getFullYear()) * 12; 
        months -= creation.getMonth(); 
        months += now.getMonth(); 
        const years = Math.floor(months / 12); 
        if (years > 0) return years === 1 ? '1y' : `${years}y`; 
        return months > 0 ? `${months}mo` : '0y'; 
    }

    titleCase(str) {
        if (!str) return 'Unknown';
        if (this.GROUP_MAP[str]) return this.GROUP_MAP[str];
        return str.split('_').map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(' ');
    }

    generate(intelData) {
        const {
            character,
            corporation,
            alliance,
            stats,
            analysis,
            recent_killmails,
            lookup_timestamp,
            data_source,
            character_id
        } = intelData;

        if (!character || !corporation || !stats || !analysis) {
            console.error("Report Generator: Incomplete data. Missing: character, corporation, stats, or analysis.");
            return '❌ **Error**: Incomplete intel data received. Cannot generate report.';
        }

        // --- SECTION 1: HEADER ---
        const charName = character.name || 'Unknown';
        const charBirthday = character.birthday;
        const charId = character_id; // Use the root-level character_id
        const secStatus = character.security_status || 0;
        const targetAllianceId = character.alliance_id;
        const reasonsText = (analysis.threat_reasons && Array.isArray(analysis.threat_reasons)) ? analysis.threat_reasons.join(', ') : 'N/A';

        const lines = ['```ansi'];
        lines.push(`${this.styles.HEADING}⚡ TACTICAL INTEL BRIEF${this.colors.RESET}`);
        lines.push('');
        lines.push(`${this.styles.LABEL}TARGET: ${this.colors.RESET}${this.styles.VALUE_NEUTRAL}${charName}${this.colors.RESET}`);
        lines.push(`${this.styles.LABEL}STANDINGS: ${this.colors.RESET}${this.getStandingsStyle(targetAllianceId)}${this.colors.RESET}`);
        lines.push(`${this.styles.LABEL}THREAT: ${this.colors.RESET}${this.getRiskEmoji(analysis.threat_level)} ${this.styles.VALUE_NEUTRAL}${analysis.threat_level?.toUpperCase() || 'UNKNOWN'}${this.colors.RESET}`);
        lines.push(`${this.styles.LABEL}REASON: ${this.colors.RESET}${this.styles.VALUE_HIGHLIGHT}${reasonsText}${this.colors.RESET}`);
        lines.push(`${this.styles.LABEL}AGE: ${this.colors.RESET}${this.styles.VALUE_NEUTRAL}${this.formatCharacterAge(charBirthday)}${this.colors.RESET}`);
        lines.push(`${this.styles.LABEL}SEC STATUS: ${this.colors.RESET}${this.getSecStatusEmoji(secStatus)} ${this.styles.VALUE_NEUTRAL}${secStatus.toFixed(2)}${this.colors.RESET}`);
        lines.push('');

        // --- SECTION 2: COMBAT RECORD (from LIFETIME `stats`) ---
        lines.push(`${this.styles.HEADING}📊 LIFETIME COMBAT RECORD (HYBRID)${this.colors.RESET}`);
        const zkill_kills = stats.shipsDestroyed || 0;
        const zkill_losses = stats.shipsLost || 0;
        const zkill_isk_destroyed = stats.iskDestroyed || 0;
        const zkill_isk_lost = stats.iskLost || 0;
        const zkill_danger_ratio = stats.dangerRatio || 0;
        const zkill_gang_ratio = stats.gangRatio || 0;

        const zkillKL = `${zkill_kills > 0 ? this.styles.VALUE_GOOD : this.styles.VALUE_NEUTRAL}${zkill_kills}${this.colors.RESET}/${zkill_losses > 0 ? this.styles.VALUE_BAD : this.styles.VALUE_NEUTRAL}${zkill_losses}${this.colors.RESET}`;
        lines.push(`${this.styles.LABEL}  - Kills/Losses: ${zkillKL}`);
        lines.push(`${this.styles.LABEL}  - ISK Destroyed: ${this.colors.RESET}${this.styles.VALUE_ISK}${this.formatISK(zkill_isk_destroyed)}${this.colors.RESET}`);
        lines.push(`${this.styles.LABEL}  - ISK Lost: ${this.colors.RESET}${this.styles.VALUE_BAD}${this.formatISK(zkill_isk_lost)}${this.colors.RESET}`);
        lines.push(`${this.styles.LABEL}  - Danger Ratio: ${this.colors.RESET}${this.styles.VALUE_NEUTRAL}${zkill_danger_ratio.toFixed(1)}%${this.colors.RESET}`);
        lines.push(`${this.styles.LABEL}  - Gang Ratio: ${this.colors.RESET}${this.styles.VALUE_NEUTRAL}${zkill_gang_ratio.toFixed(1)}%${this.colors.RESET}`);
        lines.push('');

        // --- SECTION 3: OPERATIONAL AREA (from LIFETIME `stats`) ---
        lines.push(`${this.styles.HEADING}🌍 OPERATIONAL AREA (LIFETIME)${this.colors.RESET}`);
        const locLabels = stats?.labels || {};
        let primaryArea = 'Unknown';
        let maxActivity = 0;

        const hsKills = locLabels['loc:highsec']?.shipsDestroyed || 0;
        const lsKills = locLabels['loc:lowsec']?.shipsDestroyed || 0;
        const nsKills = locLabels['loc:nullsec']?.shipsDestroyed || 0;
        const whKills = locLabels['loc:w-space']?.shipsDestroyed || 0;

        if (nsKills > maxActivity) { primaryArea = 'Nullsec'; maxActivity = nsKills; }
        if (lsKills > maxActivity) { primaryArea = 'Lowsec'; maxActivity = lsKills; }
        if (whKills > maxActivity) { primaryArea = 'W-Space'; maxActivity = whKills; }
        if (hsKills > maxActivity) { primaryArea = 'Highsec'; maxActivity = hsKills; }

        lines.push(`${this.styles.LABEL}  - Primary Area: ${this.colors.RESET}${this.styles.VALUE_HIGHLIGHT}${primaryArea.toUpperCase()}${this.colors.RESET}`);

        const topSystemsList = stats?.topLists?.find(list => list.type === 'solarSystem' || list.type === 'system')?.data || [];

        if (topSystemsList.length > 0) {
            const systemsText = topSystemsList.slice(0, 3)
                .map(s => `${s.solarSystemName || s.name || `ID ${s.solarSystemID}`} (${s.kills})`)
                .join(', ');
            lines.push(`${this.styles.LABEL}  - Top Systems: ${this.colors.RESET}${this.styles.VALUE_NEUTRAL}${systemsText}${this.colors.RESET}`);
        }

        const totalKillsForMix = zkill_kills > 0 ? zkill_kills : 1;
        const secParts = [];
        if (hsKills > 0) secParts.push(`${((hsKills / totalKillsForMix) * 100).toFixed(0)}% HS`);
        if (lsKills > 0) secParts.push(`${((lsKills / totalKillsForMix) * 100).toFixed(0)}% LS`);
        if (nsKills > 0) secParts.push(`${((nsKills / totalKillsForMix) * 100).toFixed(0)}% NS`);
        if (whKills > 0) secParts.push(`${((whKills / totalKillsForMix) * 100).toFixed(0)}% WH`);

        if (secParts.length > 0) {
            lines.push(`${this.styles.LABEL}  - Security Mix: ${this.colors.RESET}${this.styles.VALUE_NEUTRAL}${secParts.join(', ')}${this.colors.RESET}`);
        }
        lines.push('');

        // --- SECTION 4: ORG & HISTORY ---
        lines.push(`${this.styles.HEADING}🏢 ORG & HISTORY${this.colors.RESET}`);
        lines.push(`${this.styles.LABEL}  - CORP: ${this.colors.RESET}${this.styles.VALUE_NEUTRAL}${corporation.name || 'Unknown'} [${corporation.ticker || '???'}]${this.colors.RESET}`);
        if (alliance && alliance.name) { 
            lines.push(`${this.styles.LABEL}  - ALLIANCE: ${this.colors.RESET}${this.styles.VALUE_NEUTRAL}${alliance.name} [${alliance.ticker || '???'}]${this.colors.RESET}`); 
