        lines.push('');

        // --- SECTION 5: PREFERRED SHIPS (from LIFETIME `stats`) ---
        lines.push(`${this.styles.HEADING}🚢 PREFERRED SHIP CLASSES (LIFETIME KILLS)${this.colors.RESET}`);
        const groupStats = stats?.groups || {};
        const shipClasses = [];

        for (const groupId in groupStats) {
            const groupData = groupStats[groupId];
            if (groupData.shipsDestroyed > 0 && this.GROUP_MAP[groupId]) {
                shipClasses.push({
                    name: this.GROUP_MAP[groupId],
                    count: groupData.shipsDestroyed
                });
            }
        }

        if (shipClasses.length > 0) {
            const topClasses = shipClasses
                .sort((a, b) => b.count - a.count)
                .slice(0, 4)
                .map(s => `${s.name} (${s.count})`)
                .join(', ');

            lines.push(`${this.styles.LABEL}  - Top Classes: ${this.colors.RESET}${this.styles.VALUE_HIGHLIGHT}${topClasses}${this.colors.RESET}`);
        } else {
            lines.push(`${this.styles.LABEL}  - No specific ship class pattern found.${this.colors.RESET}`);
        }
        lines.push('');

        // --- SECTION 6: RECENT ACTIVITY (from `recent_killmails`) ---
        lines.push(`${this.styles.HEADING}🛰️ RECENT COMBAT ACTIVITY${this.colors.RESET}`);
        const recentKills = recent_killmails || [];
        // Get the name map passed from the assembly node
        const idNameMap = stats?.info?.idNameMap || {};

        if (recentKills.length > 0) {
            recentKills.slice(0, 5).forEach(km => {
                if (!km || !km.victim) return;
                const isLoss = (km.victim.character_id === charId);

                const zkbData = km.zkb || {};
                const totalValue = km.total_value || zkbData.totalValue || 0;
                // Use the pre-fetched idNameMap for resolution
                const victimShipName = km.victim.ship_type_name || idNameMap[km.victim.shipTypeID] || `ID ${km.victim.shipTypeID || km.victim.ship_type_id}`;
                const victimCharName = km.victim.character_name || idNameMap[km.victim.character_id] || `ID ${km.victim.character_id}`;
                const systemName = km.solar_system_name || idNameMap[km.solar_system_id] || `ID ${km.solar_system_id}`;

                const statusSymbol = isLoss ? '🔴' : '🟢';
                const timeText = `${this.styles.DIM}${this.formatTimeAgo(km.killmail_time)}`;
                const systemText = `in ${this.styles.VALUE_HIGHLIGHT}${systemName}${this.colors.RESET}`;

                let victimText;
                if (isLoss) {
                  victimText = `${this.styles.VALUE_NEUTRAL}${victimShipName}`;
                } else {
                  victimText = `vs ${this.styles.VALUE_NEUTRAL}${victimShipName} (${victimCharName})`;
                }

                const valueText = totalValue > 0 ? `(${this.styles.VALUE_ISK}${this.formatISK(totalValue)}${this.styles.DIM})` : '';

                lines.push(`  ${statusSymbol} ${timeText} ${systemText}: ${victimText} ${this.styles.DIM}${valueText}${this.colors.RESET}`);
            });
        } else {
            // Fallback to last_activity if it exists (from local stats)
            const lastActivity = stats?.last_activity || stats?.info?.lastApiUpdate?.sec * 1000;
            if (lastActivity) {
                const lastSeen = this.formatTimeAgo(new Date(lastActivity).toISOString());
                lines.push(`${this.styles.LABEL}  - Last Seen: ${this.colors.RESET}${this.styles.VALUE_HIGHLIGHT}${lastSeen}${this.colors.RESET}`);
            } else {
                lines.push(`${this.styles.LABEL}  - No recent combat activity found.${this.colors.RESET}`);
            }
        }
        lines.push('');

        // --- SECTION 7: THREAT ASSESSMENT (from `analysis` object) ---
        lines.push(`${this.styles.HEADING}🛡️ THREAT ASSESSMENT${this.colors.RESET}`);
        lines.push(`${this.styles.LABEL}  - WH Operator: ${this.colors.RESET}${analysis.is_wormhole_operator ? this.styles.WORMHOLE + 'Yes' : this.styles.VALUE_GOOD + 'No'}${this.colors.RESET}`);
        lines.push(`${this.styles.LABEL}  - Capital Threat: ${this.colors.RESET}${analysis.capital_usage_detected ? this.styles.VALUE_BAD + 'Yes' : this.styles.VALUE_GOOD + 'No'}${this.colors.RESET}`);

        lines.push('');

        // --- SECTION 8: FOOTER ---
        lines.push(`${this.styles.LINE}-----------------------------------------------------${this.colors.RESET}`);

        const sourceLines = [];
        if (data_source?.stats) sourceLines.push(`Stats: ${data_source.stats}`);
        if (data_source?.killmails) sourceLines.push(`KMs: ${data_source.killmails}`);
        if (sourceLines.length > 0) {
            lines.push(`${this.styles.LABEL}📊 Data: ${this.colors.RESET}${this.styles.DIM}${sourceLines.join(' | ')}${this.colors.RESET}`);
        }

        lines.push(`${this.styles.LABEL}🤖 Generated by Alfred: ${this.colors.RESET}${this.styles.HEADING}${this.formatTimestamp(lookup_timestamp)}${this.colors.RESET}`);
        lines.push('```');
        return lines.join('\n');
    }
}

