                result = await redis.get(test.key);
            } else {
                result = await redis.hget(test.key, test.field);
            }

            let passed = false;
            let actual = result;

            if (result === null || result === undefined) {
                passed = false;
                actual = 'MISSING';
            } else if (test.expected) {
                passed = result === test.expected;
                actual = result;
            } else if (test.isJson) {
                let data;
                try {
                    data = JSON.parse(result);
                    passed = true;
                    if (test.hasField) {
                        passed = data && Object.prototype.hasOwnProperty.call(data, test.hasField);
                        actual = passed ? `FOUND field ${test.hasField}` : `MISSING field ${test.hasField}`;
                    } else if (test.hasFields) {
                        const missingFields = test.hasFields.filter(f => !data || !Object.prototype.hasOwnProperty.call(data, f));
