                        actual = `Length: ${result.length}`;
                    } else if (test.isNonEmptyArray) {
                        passed = Array.isArray(data) && data.length > 0;
                        actual = `IsArray: ${Array.isArray(data)}, Length: ${data?.length || 0}`;
                    }
                } catch (e) {
                    passed = false;
                    actual = `INVALID JSON: ${e.message}`;
                }
            } else if (test.hasField) {
                let data;
                try {
                    data = JSON.parse(result);
                    passed = data && Object.prototype.hasOwnProperty.call(data, test.hasField);
                    actual = passed ? `FOUND field ${test.hasField}` : `MISSING field ${test.hasField}`;
                } catch(e) {
                    passed = false;
                    actual = `INVALID JSON: ${e.message}`;
                }
            } else if (test.hasFields) {
                let data;
                try {
                    data = JSON.parse(result);
                    const missingFields = test.hasFields.filter(f => !data || !Object.prototype.hasOwnProperty.call(data, f));
                    passed = missingFields.length === 0;
                    actual = passed ? 'Found all fields' : `Missing fields: ${missingFields.join(', ')}`;
                } catch(e) {
                    passed = false;
                    actual = `INVALID JSON: ${e.message}`;
                }
            } else if (test.contains) {
                passed = result.includes(test.contains);
                actual = `(Data too long to display)`;
            }

            report.data_verification[test.description] = {
                status: passed ? 'PASS' : 'FAIL',
                actual: actual
            };
            if (passed) passedTests++;

        } catch (error) {
            report.data_verification[test.description] = { status: 'ERROR', error: error.message };
        }
    }

    // --- ADVANCED VERIFICATION ---
    console.log('\n🔍 Running advanced verification spot-checks...');

    totalTests++;
    try {
        const testId = '30000142';
        const nameFromId = await redis.hget('eve:id_to_name', testId);
        if (!nameFromId) throw new Error(`Failed to resolve name from ID ${testId}`);
        const idFromName = await redis.hget('eve:name_to_id', nameFromId.toLowerCase());
        if (!idFromName) throw new Error(`Failed to resolve ID from name ${nameFromId}`);
        const passed = (idFromName === testId);
        report.data_verification['B1: Bidirectional Name (Jita)'] = {
            status: passed ? 'PASS' : 'FAIL',
            expected: testId,
            actual: idFromName
        };
        if (passed) passedTests++;
    } catch (e) {
        report.data_verification['B1: Bidirectional Name (Jita)'] = { status: 'ERROR', error: e.message };
    }

    totalTests++;
    try {
        const npcCharacterId = '3019538';
        const lossCount = await redis.zcard(`intel:losses:character:${npcCharacterId}`);
        const passed = (lossCount === 0);
        report.data_verification['Intel: NPC Loss Index Exclusion'] = {
            status: passed ? 'PASS' : 'FAIL',
            expected: '0 losses indexed',
            actual: `${lossCount} losses indexed`
        };
        if (passed) passedTests++;
    } catch (e) {
        report.data_verification['Intel: NPC Loss Index Exclusion'] = { status: 'ERROR', error: e.message };
    }

    totalTests++;
    try {
        const sampleKillIdArr = await redis.zrevrange('intel:kills:all', 0, 0);
        if (!sampleKillIdArr || sampleKillIdArr.length === 0) {
            report.data_verification['Intel: Geographic Index (Latest Kill)'] = { status: 'SKIPPED', message: 'No kills found in intel:kills:all' };
            totalTests--;
        } else {
            const sampleKillId = sampleKillIdArr[0];
            const kmDataStr = await redis.hget('intel:kill:data', sampleKillId);
            if (!kmDataStr) throw new Error(`Kill data for ${sampleKillId} not found`);
            const kmData = JSON.parse(kmDataStr);
            if (!kmData.space_type || (kmData.space_type !== 'wormhole' && !kmData.region_id)) {
                throw new Error(`Kill data ${sampleKillId} is missing space_type or region_id (Space: ${kmData.space_type}, Region: ${kmData.region_id})`);
            }
            const inSpaceIndex = await redis.zscore(`intel:kills:space:${kmData.space_type}`, sampleKillId);
            let inRegionIndex = null;
            if (kmData.region_id) {
                 inRegionIndex = await redis.zscore(`intel:kills:region:${kmData.region_id}`, sampleKillId);
            }

            const passed = (inSpaceIndex !== null && (inRegionIndex !== null || kmData.space_type === 'wormhole'));
            report.data_verification['Intel: Geographic Index (Latest Kill)'] = {
                status: passed ? 'PASS' : 'FAIL',
                space_index: inSpaceIndex !== null ? 'FOUND' : 'MISSING',
                region_index: kmData.space_type === 'wormhole' ? 'N/A (Wormhole)' : (inRegionIndex !== null ? 'FOUND' : 'MISSING'),
                kill_id: sampleKillId
            };
            if (passed) passedTests++;
        }
    } catch (e) {
        report.data_verification['Intel: Geographic Index (Latest Kill)'] = { status: 'ERROR', error: e.message };
    }

    totalTests++;
    try {
        const bpoTypeId = '11567';
        const classificationStr = await redis.hget('eve:item_classification', bpoTypeId);
        if (!classificationStr) throw new Error(`BPO classification for ${bpoTypeId} not found`);
        const classification = JSON.parse(classificationStr);
        const expectedGroupId = 775;
        const actualGroupId = classification ? classification.groupID : null;
        const passed = (classification && actualGroupId === expectedGroupId);

        report.data_verification['B2: Blueprint Classification (Rorqual)'] = {
            status: passed ? 'PASS' : 'FAIL',
            expected: `groupID ${expectedGroupId} (Capital Blueprints)`,
            actual: `groupID ${actualGroupId}`
        };
        if (passed) passedTests++;

        if (!passed && actualGroupId !== null) {
            report.warnings.push(`SDE Data CORRUPT: Rorqual Blueprint (11567) has wrong groupID ${actualGroupId}, expected ${expectedGroupId}. Re-run SDE indexer.`);
        }

    } catch (e) {
        report.data_verification['B2: Blueprint Classification (Rorqual)'] = { status: 'ERROR', error: e.message };
    }

    // --- DATA QUALITY ---
    console.log('\n🔬 Sampling data quality...');
    try {
        const recentKillIds = await redis.zrevrange('intel:kills:all', 0, 99);
        const sampleSize = Math.min(recentKillIds.length, 100);

        let incompleteResolution = 0;
        let missingValues = 0;
        let npcKills = 0;

        if (sampleSize > 0) {
            const qualityPipeline = redis.pipeline();
            recentKillIds.forEach(id => qualityPipeline.hget('intel:kill:data', id));
            const killDataResults = await qualityPipeline.exec();

            for (const [err, killData] of killDataResults) {
                if (killData && !err) {
                    try {
                        const km = JSON.parse(killData);
                        let hasIncomplete = false;
                        if (km.victim?.character_name && km.victim.character_name.startsWith('Unknown ID:')) {
                            hasIncomplete = true;
                        }
                        if (km.attackers) {
                            for (const att of km.attackers) {
                                if (att.character_name && att.character_name.startsWith('Unknown ID:')) {
                                    hasIncomplete = true;
                                    break;
                                }
                            }
                        }
                        if (hasIncomplete) incompleteResolution++;

                        if (!km.total_value || km.total_value === 0) {
                            if (km.victim?.ship_type_id !== 670) {
                                missingValues++;
                            }
                        }
                        if (km.victim?.is_npc) {
                            npcKills++;
                        }
                    } catch (e) {
                        console.error(`Failed to parse kill for quality check: ${e.message}`);
                    }
                }
            }
        }

        const now = Date.now();
        const oneHourAgo = now - (60 * 60 * 1000);
        const recentKillsCount = await redis.zcount('intel:kills:all', Math.floor(oneHourAgo / 1000), Math.floor(now / 1000));
        const qualityStatus = (sampleSize === 0) ? 'NO_DATA' : (((incompleteResolution / sampleSize) > 0.3 || (missingValues / sampleSize) > 0.1) ? 'WARNING' : 'GOOD');

        report.data_quality = {
            overall_quality: qualityStatus,
            sample_size: sampleSize,
            incomplete_resolution: {
                count: incompleteResolution,
                percent: sampleSize > 0 ? ((incompleteResolution / sampleSize) * 100).toFixed(1) : 0
            },
            missing_values: {
                count: missingValues,
                percent: sampleSize > 0 ? ((missingValues / sampleSize) * 100).toFixed(1) : 0
            },
            npc_kills_in_sample: {
                count: npcKills,
                percent: sampleSize > 0 ? ((npcKills / sampleSize) * 100).toFixed(1) : 0
            },
            recent_activity: {
                kills_last_hour: recentKillsCount,
                status: recentKillsCount > 0 ? 'ACTIVE' : 'IDLE'
            }
        };

        if (qualityStatus === 'WARNING') report.warnings.push('Data quality is WARNING (high rate of incomplete resolution or missing values).');
        if (recentKillsCount === 0 && report.killmail_pipeline.total_killmails_stored > 0) report.warnings.push('Killmail ingestion appears to be IDLE (0 kills in last hour).');
    } catch (error) {
        report.data_quality = { status: 'ERROR', error: error.message };
    }

    // --- INGESTION METRICS ---
    console.log('\n📈 Calculating ingestion metrics...');
    try {
        const now = Date.now();
        const oneHourAgo = now - (60 * 60 * 1000);
        const oneDayAgo = now - (24 * 60 * 60 * 1000);
        const oneWeekAgo = now - (7 * 24 * 60 * 60 * 1000);

        const ratePipeline = redis.pipeline();
        ratePipeline.zcount('intel:kills:all', Math.floor(oneHourAgo / 1000), Math.floor(now / 1000));
        ratePipeline.zcount('intel:kills:all', Math.floor(oneDayAgo / 1000), Math.floor(now / 1000));
        ratePipeline.zcount('intel:kills:all', Math.floor(oneWeekAgo / 1000), Math.floor(now / 1000));
        const rateResults = await ratePipeline.exec();

        const killsLastHour = rateResults[0][1];
        const killsLastDay = rateResults[1][1];
        const killsLastWeek = rateResults[2][1];

        const recentKillIds = await redis.zrevrangebyscore('intel:kills:all', now, oneDayAgo, 'LIMIT', 0, 1000);
        let totalValue24h = 0;
        let highValueKills24h = 0;

        if(recentKillIds.length > 0) {
            const valuePipeline = redis.pipeline();
            recentKillIds.forEach(id => valuePipeline.hget('intel:kill:data', id));
            const valueResults = await valuePipeline.exec();

            for (const [err, killData] of valueResults) {
                if (killData && !err) {
                    try {
                        const km = JSON.parse(killData);
                        if (km.total_value) {
                            totalValue24h += km.total_value;
                            if (km.total_value > 1000000000) highValueKills24h++;
                        }
                    } catch (e) {
                        // Ignore parse errors
                    }
                }
            }
        }

        const spaceTypes = ['highsec', 'lowsec', 'nullsec', 'wormhole'];
        const spaceDistribution = {};
        const spacePipeline = redis.pipeline();
        for (const space of spaceTypes) {
            spacePipeline.zcount(`intel:kills:space:${space}`, oneDayAgo, now);
        }
        const spaceResults = await spacePipeline.exec();
        spaceTypes.forEach((space, i) => spaceDistribution[space] = spaceResults[i][1]);

        const fleetSizes = ['solo', 'small', 'medium', 'large'];
        const fleetDistribution = {};
        const fleetPipeline = redis.pipeline();
        for (const size of fleetSizes) {
            fleetPipeline.zcount(`intel:kills:fleet:${size}`, oneDayAgo, now);
        }
        const fleetResults = await fleetPipeline.exec();
        fleetSizes.forEach((size, i) => fleetDistribution[size] = fleetResults[i][1]);

        console.log(`\n(Scanning systems for 24h stats... this may take a moment)`);
        const systemKeysAll = await scanAll('intel:kills:system:*');
        const topSystems = [];
        const systemPipeline = redis.pipeline();

        let keysToScan = systemKeysAll;
        if(systemKeysAll.length > TOP_SYSTEM_SCAN_LIMIT) {
            console.warn(`WARNING: Found ${systemKeysAll.length} system keys. Sampling ${TOP_SYSTEM_SCAN_LIMIT} to avoid timeout.`);

            keysToScan = [];
            const indices = new Set();
            while (indices.size < TOP_SYSTEM_SCAN_LIMIT) {
                indices.add(Math.floor(Math.random() * systemKeysAll.length));
            }
            for(const index of indices) {
                keysToScan.push(systemKeysAll[index]);
            }
        }

        keysToScan.forEach(systemKey => {
             systemPipeline.zcount(systemKey, oneDayAgo, now);
        });
        const systemCountResults = await systemPipeline.exec();

        const systemNamePipeline = redis.pipeline();
        const validSystemCounts = [];

        for (let i = 0; i < keysToScan.length; i++) {
            const count = systemCountResults[i][1];
            if (count > 0) {
                const systemKey = keysToScan[i];
                const parts = systemKey.split(':');
                const systemId = parts.length > 3 ? parts[3] : null;
                if (systemId) {
                    validSystemCounts.push({ system_id: systemId, kills_24h: count });
                    systemNamePipeline.hget('eve:id_to_name', systemId);
                }
            }
        }

        const systemNameResults = await systemNamePipeline.exec();

        validSystemCounts.forEach((system, i) => {
            const name = systemNameResults[i][1];
            system.system_name = name || `ID: ${system.system_id}`;
            topSystems.push(system);
        });

        topSystems.sort((a, b) => b.kills_24h - a.kills_24h);

        report.ingestion_metrics = {
            rate: {
                kills_per_hour: killsLastHour,
                kills_per_day: killsLastDay,
                kills_per_week: killsLastWeek,
                average_per_hour_7d: Math.round(killsLastWeek / (7 * 24) || 0)
            },
            value_destroyed_24h_sample: {
                total_isk: totalValue24h,
                formatted: (totalValue24h / 1000000000).toFixed(2) + 'B ISK',
                high_value_kills_gt_1b: highValueKills24h,
                sample_size: recentKillIds.length
            },
            space_distribution_24h: spaceDistribution,
            fleet_distribution_24h: fleetDistribution,
            top_systems_24h: topSystems.slice(0, 5)
        };
    } catch (error) {
        report.ingestion_metrics = { status: 'ERROR', error: error.message };
    }

    // --- PERFORMANCE METRICS ---
    console.log('\n📅 Checking data freshness & performance...');
    try {
        const lastSdeUpdate = await redis.get('sde:last_update');
        if (lastSdeUpdate) {
            const updateInfo = JSON.parse(lastSdeUpdate);
            const lastUpdate = new Date(updateInfo.storage_time);
            const hoursAgo = (Date.now() - lastUpdate.getTime()) / (1000 * 60 * 60);

            report.performance_metrics.sde_freshness = {
                status: hoursAgo < 25 ? 'FRESH' : hoursAgo < 48 ? 'ACCEPTABLE' : 'STALE',
                last_update: updateInfo.storage_time,
                hours_ago: Math.round(hoursAgo * 10) / 10,
                files_stored: updateInfo.files_stored,
                total_size_mb: updateInfo.total_size_mb
            };

            if (hoursAgo > 48) {
                report.warnings.push(`SDE data is ${Math.round(hoursAgo)} hours old`);
            }
        } else {
            report.performance_metrics.sde_freshness = { status: 'UNKNOWN', message: 'No timestamp found' };
            report.warnings.push('SDE update timestamp not found - cannot determine data age');
        }

        const marketMetadataJson = await redis.get('eve:market:prices:metadata');
        if (marketMetadataJson) {
            const metadata = JSON.parse(marketMetadataJson);
            const lastUpdate = new Date(metadata.last_update);
            const hoursAgo = (Date.now() - lastUpdate.getTime()) / (1000 * 60 * 60);

            report.performance_metrics.market_freshness = {
                status: hoursAgo < 26 ? 'FRESH' : 'STALE',
                last_update: metadata.last_update,
                hours_ago: Math.round(hoursAgo * 10) / 10,
                total_prices: metadata.total_prices
            };
            if (hoursAgo > 26) {
                report.critical_issues.push('Market prices are STALE (over 26 hours old).');
            }
        } else {
            report.performance_metrics.market_freshness = { status: 'UNKNOWN', message: 'No metadata found' };
        }

        const totalResolved = await redis.hlen('eve:id_to_name');

        const unknownPattern = await redis.hscan('eve:id_to_name', 0, 'MATCH', 'Unknown ID:*', 'COUNT', 10000);
        let unknownCount = 0;
        if (unknownPattern && unknownPattern[1]) {
            unknownCount = unknownPattern[1].filter((v, i) => i % 2 === 1 && v.startsWith('Unknown ID:')).length;
        }

        report.performance_metrics.name_resolution = {
            total_cached: totalResolved,
            failed_lookups_cached_sample: unknownCount,
            success_rate_percent: totalResolved > 0 ? ((1 - (unknownCount / totalResolved)) * 100).toFixed(2) : '100.00'
        };
    } catch (error) {
        report.performance_metrics.sde_freshness = { status: 'ERROR', error: error.message };
        report.performance_metrics.market_freshness = { status: 'ERROR', error: error.message };
    }

    // --- FINALIZE STATUS ---
    const verificationFailures = Object.values(report.data_verification).filter(v => v.status === 'FAIL').length;
    if (verificationFailures > 0) {
        report.warnings.push(`Data verification failed for ${verificationFailures} test(s).`);
    }

    if (criticalSdeFailures > 0 || report.critical_issues.length > 0) {
        report.overall_status = 'CRITICAL';
    } else if (sdeWarnings > 5 || (report.warnings.length > 0 && !report.warnings.every(w => w.startsWith("Too many system keys"))) || report.redis_health.status === 'WARNING') {
        report.overall_status = 'WARNING';
    } else if (report.killmail_pipeline.status === 'INACTIVE') {
        report.overall_status = 'WARNING';
    }

    if (report.overall_status === 'CRITICAL') {
        report.recommendations.push('🔧 One or more critical systems are down. Immediate review required.');
    } else if (report.overall_status === 'WARNING') {
        const realWarnings = report.warnings.filter(w => !w.startsWith("Too many system keys"));
        if (realWarnings.length > 0) {
            report.recommendations.push('⚠️ System is degraded. Review warnings.');
        } else {
            report.recommendations.push('🎉 All systems operating normally');
            report.overall_status = 'HEALTHY';
        }
    } else {
        report.recommendations.push('🎉 All systems operating normally');
    }

    if (criticalSdeFailures > 0) {
         report.recommendations.push('🔧 Run SDE indexing workflow immediately to populate missing critical indexes.');
    }

    const whData = report.sde_indexes['sde:raw:anoik_is_wormholes_json'];
    if (whData && whData.status === 'HEALTHY' && whData.item_count > 0) {
        report.recommendations.push('📊 Wormhole data: Embedded Anoik.is dataset is present and indexed.');
    }

    const marketStatus = report.sde_indexes['eve:market:prices']?.status;
    if (marketStatus === 'CRITICAL' || report.performance_metrics.market_freshness?.status === 'STALE') {
        if (!report.recommendations.some(r => r.includes('Market Price Indexer'))) {
            report.recommendations.push('💰 Run the "Market Price Indexer" workflow immediately to refresh stale ESI price data.');
        }
    }

    if (report.pipeline_status?.ingestion?.status === 'IDLE' || report.pipeline_status?.processing?.status === 'IDLE') {
        report.recommendations.push('🤖 Check ingestion/processing workers - heartbeats are missing.');
    }
    if (report.pipeline_status?.queue?.status === 'BACKLOG') {
        report.recommendations.push('📈 Killmail queue is backlogged - check processing workers for errors or scaling.');
    }
    if (report.data_quality?.overall_quality === 'WARNING') {
        report.recommendations.push('🧬 Data quality is suffering. Check name resolution and value pipeline.');
    }
    if (verificationFailures > 0) {
        report.recommendations.push('🧪 Data verification tests are failing. SDE data is corrupt or indexing logic is broken.');
    }

    report.summary = {
        total_sde_indexes: Object.keys(sdeIndexes).length,
        healthy_sde_indexes: healthyIndexes,
        total_sde_items: totalSdeItems,
        critical_failures: report.critical_issues.length,
        warnings: report.warnings.length,
        verification_tests_passed: `${passedTests}/${totalTests}`
    };

    // --- CONSOLE SUMMARY ---
    const hr = '='.repeat(80);
    console.log('\n' + hr);
    console.log('📊 COMPREHENSIVE HEALTH REPORT (v2.4)');
    console.log(hr);
    console.log(`\n🏥 OVERALL STATUS: ${report.overall_status}`);

    console.log('\n' + hr);
    console.log('⚙️  PROCESS PIPELINE STATUS');
    console.log(hr);
    console.log(`    Poller (zKill): ${report.pipeline_status.ingestion.status} (TTL: ${report.pipeline_status.ingestion.ttl_remaining}s)`);
    console.log(`    Queue Backlog: ${report.pipeline_status.queue.depth} items (${report.pipeline_status.queue.status})`);
    console.log(`    Processors:    ${report.pipeline_status.processing.active_workers}/${report.pipeline_status.processing.expected_workers} Active`);

    console.log('\n' + hr);
    console.log(`📈 CURRENT INGESTION RATE`);
    console.log(hr);
    console.log(`    Last Hour: ${report.ingestion_metrics.rate.kills_per_hour.toLocaleString()} kills`);
    console.log(`    Last 24 Hrs: ${report.ingestion_metrics.rate.kills_per_day.toLocaleString()} kills`);
    console.log(`    7-Day Avg:   ${report.ingestion_metrics.rate.average_per_hour_7d.toLocaleString()} kills/hr`);

    console.log('\n' + hr);
    console.log(`🧬 100-KILL SAMPLE & DATA QUALITY`);
    console.log(hr);
    console.log(`    Overall Quality: ${report.data_quality.overall_quality}`);
    console.log(`    Incomplete Names: ${report.data_quality.incomplete_resolution.percent}% (${report.data_quality.incomplete_resolution.count}/${report.data_quality.sample_size})`);
    console.log(`    Missing Values:   ${report.data_quality.missing_values.percent}% (${report.data_quality.missing_values.count}/${report.data_quality.sample_size})`);

    console.log('\n' + hr);
    console.log(`📚 SDE & DATA FRESHNESS`);
    console.log(hr);
    console.log(`    SDE Indexes: ${report.summary.healthy_sde_indexes}/${report.summary.total_sde_indexes} Healthy`);
    console.log(`    SDE Data:    ${report.performance_metrics.sde_freshness.status} (${report.performance_metrics.sde_freshness.hours_ago} hrs old)`);
    console.log(`    Market Prices: ${report.performance_metrics.market_freshness.status} (${report.performance_metrics.market_freshness.hours_ago} hrs old)`);
    console.log(`    Verification:  ${report.summary.verification_tests_passed} Passed`);

    const finalRecommendations = report.recommendations.filter(r => !r.includes('All systems operating normally') && !r.startsWith("Too many system keys"));

    if (report.critical_issues.length > 0 || finalRecommendations.length > 0) {
        console.log('\n' + hr);
        console.log('❗️ ISSUES & RECOMMENDATIONS');
        console.log(hr);

        report.critical_issues.forEach(issue => console.log(`    [CRITICAL] ${issue}`));
        report.warnings.filter(w => !w.startsWith("Too many system keys")).forEach(issue => console.log(`    [WARNING]  ${issue}`));

        console.log('\n    Recommendations:');
        finalRecommendations.forEach(rec => console.log(`    - ${rec}`));
    } else {
        console.log('\n' + hr);
        console.log('     🎉 All systems operating normally');
        console.log(hr);
    }
    console.log(hr + '\n');

    return [{ json: report }];
} catch (error) {
    console.error('❌ Health Check Failed:', error && error.message ? error.message : error);
    return [{
        json: {
            timestamp: new Date().toISOString(),
            overall_status: 'ERROR',
            error: error && error.message ? error.message : String(error),
            stack: error && error.stack ? error.stack : null
        }
    }];
} finally {
    if (redis && redis.status === 'ready') {
        try {
            await redis.quit();
        } catch (e) {
            // Ignore quit errors
        }
    }
}

