    statsPipeline.zrange('intel:kills:all', 0, 0, 'WITHSCORES'); // 1
    statsPipeline.zrevrange('intel:kills:all', 0, 0, 'WITHSCORES'); // 2
    statsPipeline.hlen('eve:id_to_name'); // 3
    statsPipeline.hlen('intel:kill:data'); // 4

    // 2. Process Health Stats
    statsPipeline.get('ingestion.active'); // 5 (Poller heartbeat)
    statsPipeline.llen('intel:queue:pending'); // 6 (Queue length)

    const statsResults = await statsPipeline.exec();

    // 3. Find Active Workers (SCAN is safer than KEYS)
    let cursor = '0';
    const workerKeys = [];
    do {
        const scanResult = await redis.scan(cursor, 'MATCH', 'processing:worker:*', 'COUNT', 100);
        cursor = scanResult[0];
        workerKeys.push(...scanResult[1]);
    } while (cursor !== '0');

    const workerTTLpipeline = redis.pipeline();
    workerKeys.forEach(key => workerTTLpipeline.ttl(key));
    const workerTTLs = await workerTTLpipeline.exec();

    const activeWorkers = workerKeys.map((key, i) => {
        return { 
            key: key.replace('processing:worker:', 'Worker '), 
            ttl: workerTTLs[i][1] 
        };
    });

    const overallStats = {
        total_killmails: statsResults[0][1] || 0,
        oldest_kill: statsResults[1][1] && statsResults[1][1].length > 0 ? { id: statsResults[1][1][0], timestamp: new Date(parseInt(statsResults[1][1][1]) * 1000).toISOString() } : { id: 'N/A', timestamp: 'N/A' },
        newest_kill: statsResults[2][1] && statsResults[2][1].length > 0 ? { id: statsResults[2][1][0], timestamp: new Date(parseInt(statsResults[2][1][1]) * 1000).toISOString() } : { id: 'N/A', timestamp: 'N/A' },
        total_resolved_entities: statsResults[3][1] || 0,
        total_kill_hashes: statsResults[4][1] || 0,

        // Process stats
        pipeline_health: {
            poller_heartbeat: statsResults[5][1] ? `ACTIVE (Last seen: ${statsResults[5][1]})` : 'INACTIVE',
            pending_queue_length: statsResults[6][1] || 0,
            active_workers: activeWorkers
        }
    };

    console.log('✅ Overall stats fetched.\n');


    // ===== HELPER FUNCTION: Check if a field is properly resolved =====
    function isFieldResolved(value, fieldName) {
        // Null/undefined = not resolved
        if (!value) return false;

        // "Unknown" (generic) = not resolved
        if (value === 'Unknown') return false;

        // "undefined" (string) = not resolved
        if (value === 'undefined') return false;

        // "Unknown Item ID" prefix = not resolved
        if (value.startsWith('Unknown Item ID')) return false;

        // NEW: "Unknown ID: X" = failed lookup but CACHED (treat as resolved)
        // This is an expected failure (deleted char, invalid ID, etc.)
        if (value.startsWith('Unknown ID:')) return true;

        // "None" is valid for alliance_name
        if (fieldName === 'alliance_name' && value === 'None') return true;

        // "Player Asset" labels are valid
        if (value.startsWith('Player Asset (')) return true;

        // "NPC (" labels are valid
        if (value.startsWith('NPC (')) return true;

        // Otherwise, it's resolved
        return true;
    }

    // ===== FETCH LAST 100 KILLMAILS (The Sample) =====
    console.log('📊 Fetching last 100 killmails from intel:kills:all for sample...');
    const killIds = await redis.zrevrange('intel:kills:all', 0, 99, 'WITHSCORES');

    if (!killIds || killIds.length === 0) {
        console.log('❌ No killmails found in intel:kills:all index!');
        return [{ json: { 
            status: 'critical', 
            message: 'No killmails in database',
            overall_database_stats: overallStats,
            timestamp: new Date().toISOString()
        }}];
    }

    // Parse killIds array (Redis returns [id, score, id, score, ...])
    const killmailData = [];
    for (let i = 0; i < killIds.length; i += 2) {
        killmailData.push({
            killmail_id: killIds[i],
            index_timestamp: parseInt(killIds[i + 1])
        });
    }

    console.log(`✅ Found ${killmailData.length} killmails for sample\n`);

    // ===== FETCH FULL KILLMAIL DATA FOR SAMPLE =====
    console.log('📥 Fetching full killmail data for sample...');
    const killmailIds = killmailData.map(k => k.killmail_id);
    const killmailStrings = await redis.hmget('intel:kill:data', ...killmailIds);

    // ===== ANALYZE EACH KILLMAIL IN SAMPLE =====
    const now = Date.now();
    const healthReport = {
        total_checked: killmailData.length,
        healthy: 0,
        warnings: 0,
        errors: 0,
        overall_database_stats: overallStats,
        sample_stats: {
            avg_ingestion_delay_seconds: 0,
            oldest_kill_age_hours: 0,
            newest_kill_age_seconds: 0,
            missing_data_count: 0,
            incomplete_resolution_count: 0,
            failed_lookup_count: 0,
            missing_value_count: 0,
            npc_kills_count: 0
        },
        killmails: [],
    };

    let totalDelay = 0;
    let oldestKillTime = Infinity;
    let newestKillTime = 0;

    for (let i = 0; i < killmailData.length; i++) {
        const killId = killmailData[i].killmail_id;
        const indexTimestamp = killmailData[i].index_timestamp;
        const kmString = killmailStrings[i];

        const analysis = {
            killmail_id: killId,
            index_position: i + 1,
            status: 'healthy',
            issues: [],
            warnings: [],
            details: {}
        };

        // Check if killmail data exists
        if (!kmString) {
            analysis.status = 'error';
            analysis.issues.push('❌ Killmail data missing from intel:kill:data hash');
            healthReport.errors++;
            healthReport.sample_stats.missing_data_count++;
            healthReport.killmails.push(analysis);
            continue;
        }

        let km;
        try {
            km = JSON.parse(kmString);
        } catch (e) {
            analysis.status = 'error';
            analysis.issues.push(`❌ Failed to parse killmail JSON: ${e.message}`);
            healthReport.errors++;
            healthReport.killmails.push(analysis);
            continue;
        }

        // ===== TIME ANALYSIS (FIXED) =====
        const killTime = new Date(km.killmail_time).getTime(); // milliseconds
        const ingestionDelay = (indexTimestamp * 1000 - killTime) / 1000; // Convert indexTimestamp to ms, then to seconds
        const ageFromNow = (now - killTime) / 1000; // seconds

        totalDelay += ingestionDelay;
        if (killTime < oldestKillTime) oldestKillTime = killTime;
        if (killTime > newestKillTime) newestKillTime = killTime;

        analysis.details.killmail_time = km.killmail_time;
        analysis.details.ingestion_delay_seconds = Math.round(ingestionDelay);
        analysis.details.age_from_now_seconds = Math.round(ageFromNow);

        if (ingestionDelay > 60) {
            analysis.warnings.push(`⚠️ Slow ingestion: ${Math.round(ingestionDelay)}s delay`);
        }

        // ===== NPC DETECTION (Uses stored flags) =====
        const victimIsNPC = km.victim?.is_npc ?? false;
        let npcAttackerCount = 0;

        if (km.attackers && Array.isArray(km.attackers)) {
            npcAttackerCount = km.attackers.filter(a => a.is_npc === true).length;
        }

        analysis.details.victim_is_npc = victimIsNPC;
        analysis.details.npc_attacker_count = npcAttackerCount;

        if (victimIsNPC) {
            healthReport.sample_stats.npc_kills_count++;
        }

        // ===== FIELD COMPLETENESS CHECK =====
        const fieldChecks = {
            core_fields: ['killmail_id', 'killmail_time', 'solar_system_id', 'victim', 'attackers'],
            enriched_fields: ['solar_system_name', 'total_value', 'is_solo', 'space_type', 'region_id'],
            victim_fields: ['character_name', 'corporation_name', 'alliance_name', 'ship_type_name'],
            attacker_fields: ['character_name', 'corporation_name', 'ship_type_name']
        };

        // Check core fields
        for (const field of fieldChecks.core_fields) {
            if (!km[field]) {
                analysis.issues.push(`❌ Missing core field: ${field}`);
                analysis.status = 'error';
            }
        }

        // Check enriched fields
        for (const field of fieldChecks.enriched_fields) {
            if (km[field] === undefined || km[field] === null) {
                // 'region_id' can be null in wormholes, so don't warn for that
                if (field === 'region_id' && km.space_type === 'wormhole') {
                   analysis.details.note_null_region = "Null region_id (expected for wormhole)";
                } else {
                   analysis.warnings.push(`⚠️ Missing enriched field: ${field}`);
                   if (analysis.status === 'healthy') analysis.status = 'warning';
                }
            }
        }

        // Check victim resolution (skip NPC warnings)
        if (km.victim) {
            const victimIsCharacter = !!km.victim.character_id;
            let unresolvedVictimFields = 0;
            let failedLookupFields = 0;

            // Only check resolution completeness if it's a PILOTED character (not NPC, and has a character ID)
            if (!victimIsNPC && victimIsCharacter) {
                for (const field of fieldChecks.victim_fields) {
                    const value = km.victim[field];

                    if (!isFieldResolved(value, field)) {
                        unresolvedVictimFields++;
                        analysis.warnings.push(`⚠️ Victim field not resolved: ${field} = "${value}"`);
                    } else if (typeof value === 'string' && value.startsWith('Unknown ID:')) {
                        failedLookupFields++;
                        analysis.details.has_failed_lookups = true;
                    }
                }

                if (unresolvedVictimFields > 0) {
                    healthReport.sample_stats.incomplete_resolution_count++;
                    if (analysis.status === 'healthy') analysis.status = 'warning';
                }

                if (failedLookupFields > 0) {
                    healthReport.sample_stats.failed_lookup_count += failedLookupFields;
                }
            } else if (!victimIsCharacter) {
                // Structures/POSes have no character ID
                analysis.details.victim_type = 'Structure/POS (Non-character)';
            } else {
                // Victim is NPC - check if properly labeled
                if (km.victim.character_name && km.victim.character_name.startsWith('NPC (')) {
                    analysis.details.npc_properly_labeled = true;
                } else if (km.victim.character_name === 'Unknown') {
                    analysis.warnings.push('⚠️ NPC victim not properly labeled (shows as "Unknown")');
                    if (analysis.status === 'healthy') analysis.status = 'warning';
                }
            }
        }

        // Check attacker resolution
        if (km.attackers && Array.isArray(km.attackers)) {
            analysis.details.attacker_count = km.attackers.length;
            let unresolvedPlayerAttackerCount = 0;
            let unresolvedNPCAttackerCount = 0;
            let failedLookupCount = 0;

            for (const attacker of km.attackers) {
                const attackerIsNPC = attacker.is_npc === true;
                const isPlayerPilot = attacker.character_id && !attackerIsNPC;
                let hasUnresolvedField = false;
                let hasFailedLookup = false;

                for (const field of fieldChecks.attacker_fields) {
                    const value = attacker[field];

                    if (!isFieldResolved(value, field)) {
                        hasUnresolvedField = true;
                        break;
                    } else if (typeof value === 'string' && value.startsWith('Unknown ID:')) {
                        hasFailedLookup = true;
                    }
                }

                if (hasFailedLookup) {
                    failedLookupCount++;
                }

                if (hasUnresolvedField) {
                    if (attackerIsNPC) {
                        // Check if NPC is properly labeled
                        if (!attacker.character_name || !attacker.character_name.startsWith('NPC (')) {
                            unresolvedNPCAttackerCount++;
                        }
                    } else if (isPlayerPilot) {
                        unresolvedPlayerAttackerCount++;
                    } else {
                        // Non-piloted entities (drones/weapons) - expected
                        analysis.details.ignored_attacker_failure = true;
                    }
                }
            }

            if (failedLookupCount > 0) {
                healthReport.sample_stats.failed_lookup_count += failedLookupCount;
                analysis.details.has_failed_lookups = true;
            }

            if (unresolvedPlayerAttackerCount > 0) {
                const totalPlayerPilots = km.attackers.filter(a => a.character_id && !a.is_npc).length;
                analysis.warnings.push(`⚠️ ${unresolvedPlayerAttackerCount}/${totalPlayerPilots} player attackers have unresolved fields`);
                healthReport.sample_stats.incomplete_resolution_count++;
                if (analysis.status === 'healthy') analysis.status = 'warning';
            }

            if (unresolvedNPCAttackerCount > 0) {
                analysis.warnings.push(`⚠️ ${unresolvedNPCAttackerCount} NPC attackers not properly labeled`);
                if (analysis.status === 'healthy') analysis.status = 'warning';
            }
        } else {
            analysis.issues.push('❌ Attackers array missing or invalid');
            analysis.status = 'error';
        }

        // Check value calculation (with Pod exclusion)
        if (km.total_value !== undefined) {
            analysis.details.total_value_isk = km.total_value.toLocaleString(undefined, { maximumFractionDigits: 2 });

            const isPod = km.victim?.ship_type_name?.includes('Capsule') || km.victim?.ship_type_name?.includes('Pod');

            if (km.total_value === 0) {
                if (!isPod) {
                    analysis.warnings.push('⚠️ Killmail has zero value (no market data?)');
                    healthReport.sample_stats.missing_value_count++;
                    if (analysis.status === 'healthy') analysis.status = 'warning';
                } else {
                    analysis.details.note_zero_isk = 'Zero-value pod killmail (expected, warning skipped)';
                }
            }
        }

        // Check solo flag
        if (km.is_solo !== undefined) {
            analysis.details.is_solo_kill = km.is_solo;
        }

        // ===== INDEX VERIFICATION (v2 - Expanded) =====
        const indexCheckPipeline = redis.pipeline();
        const killIdStr = String(killId);

        let checks = {};

        // 1. System Index
        if (km.solar_system_id) {
            checks.system = `intel:kills:system:${km.solar_system_id}`;
            indexCheckPipeline.zscore(checks.system, killIdStr);
        } else {
            analysis.warnings.push(`⚠️ Missing solar_system_id, cannot check system index.`);
        }

        // 2. Character Loss Index
        const victimIsPlayer = km.victim?.character_id && !victimIsNPC;
        if (victimIsPlayer) {
            checks.victimChar = `intel:losses:character:${km.victim.character_id}`;
            indexCheckPipeline.zscore(checks.victimChar, killIdStr);
        }

        // 3. Space Type Index
        if (km.space_type) {
            checks.spaceType = `intel:kills:space:${km.space_type}`;
            indexCheckPipeline.zscore(checks.spaceType, killIdStr);
        } else {
            analysis.warnings.push(`⚠️ Missing enriched 'space_type', cannot check index.`);
        }

        // 4. Region Index
        if (km.region_id) {
            checks.region = `intel:kills:region:${km.region_id}`;
            indexCheckPipeline.zscore(checks.region, killIdStr);
        }

        // 5. Victim Corporation Loss Index
        if (km.victim?.corporation_id) {
            checks.victimCorp = `intel:losses:corporation:${km.victim.corporation_id}`;
            indexCheckPipeline.zscore(checks.victimCorp, killIdStr);
        }

        // 6. Solo Kill Index
        if (km.is_solo === true) {
            checks.solo = 'intel:kills:fleet:solo';
            indexCheckPipeline.zscore(checks.solo, killIdStr);
        }

        // 7. Attacker Character Kill Index (Check first player attacker)
        const firstPlayerAttacker = km.attackers?.find(a => a.character_id && !a.is_npc);
        if (firstPlayerAttacker) {
            checks.attackerChar = `intel:kills:character:${firstPlayerAttacker.character_id}`;
            indexCheckPipeline.zscore(checks.attackerChar, killIdStr);
        }

        // Execute all checks
        const indexResults = await indexCheckPipeline.exec();
        let resultIndex = 0;

        // Check pipeline results
        const checkResult = (keyName) => {
            if (!checks[keyName]) return;
            const [err, score] = indexResults[resultIndex++];
            if (err) {
                analysis.issues.push(`❌ Redis error checking ${keyName} index: ${err.message}`);
            } else if (score === null) {
                analysis.issues.push(`❌ Missing from index: ${checks[keyName]}`);
                analysis.status = 'error';
            }
        };

        checkResult('system');
        checkResult('victimChar');
        checkResult('spaceType');
        checkResult('region');
        checkResult('victimCorp');
        checkResult('solo');
        checkResult('attackerChar');
        analysis.details.indexes_checked = resultIndex;

        // Separate check for incorrect NPC indexing
        if (km.victim?.character_id && victimIsNPC) {
            const inCharLossIndex = await redis.zscore(`intel:losses:character:${km.victim.character_id}`, killIdStr);
            if (inCharLossIndex !== null) {
                analysis.warnings.push(`⚠️ NPC victim incorrectly indexed in character loss index`);
                if (analysis.status === 'healthy') analysis.status = 'warning';
            } else {
                analysis.details.npc_correctly_not_indexed = true;
            }
        }

        // Update health counters
        if (analysis.status === 'healthy') {
            healthReport.healthy++;
        } else if (analysis.status === 'warning') {
            healthReport.warnings++;
        } else {
            healthReport.errors++;
        }

        healthReport.killmails.push(analysis);
    }

    // ===== CALCULATE SAMPLE STATS =====
    healthReport.sample_stats.avg_ingestion_delay_seconds = Math.round(totalDelay / killmailData.length);
    healthReport.sample_stats.oldest_kill_age_hours = ((now - oldestKillTime) / 3600000).toFixed(2);
    healthReport.sample_stats.newest_kill_age_seconds = Math.round((now - newestKillTime) / 1000);

    // ===== DETERMINE OVERALL HEALTH (based on sample) =====
    let overallHealth = 'healthy';
    if (healthReport.errors > 0) {
        overallHealth = 'critical';
    } else if (healthReport.warnings > Math.ceil(healthReport.total_checked * 0.05)) {
        overallHealth = 'degraded';
    } else if (healthReport.warnings > 0) {
        overallHealth = 'warning';
    }

    healthReport.overall_health = overallHealth;
    healthReport.timestamp = new Date().toISOString();

    // ===== VERBOSE OUTPUT (v1.10 - Human Readable) =====
    const hr = '='.repeat(80);
    console.log('\n' + hr);
    console.log('📊 KILLMAIL INGESTION PIPELINE HEALTH REPORT (v1.10)');
    console.log(hr);

    // 1. Most Pertinent: Overall Status
    console.log(`\n🏥 OVERALL STATUS: ${overallHealth.toUpperCase()}`);

    // 2. Second Most Pertinent: Process Health
    console.log('\n' + hr);
    console.log('⚙️  PROCESS PIPELINE STATUS');
    console.log(hr);
    console.log(`    Poller (zKill): ${overallStats.pipeline_health.poller_heartbeat}`);
    console.log(`    Queue Backlog: ${overallStats.pipeline_health.pending_queue_length.toLocaleString()} items`);
    console.log(`    Processors:    ${overallStats.pipeline_health.active_workers.length} Active`);
    overallStats.pipeline_health.active_workers.forEach(w => {
        console.log(`      - ${w.key} (TTL: ${w.ttl}s)`);
    });

    // 3. Third Most Pertinent: Sample Summary
    console.log('\n' + hr);
    console.log(`📊 100-KILL SAMPLE ANALYSIS`);
    console.log(hr);
    console.log(`    Result:        ✅ ${healthReport.healthy} Healthy | ⚠️ ${healthReport.warnings} Warnings | ❌ ${healthReport.errors} Errors`);
    console.log(`    Data Age:      ${healthReport.sample_stats.newest_kill_age_seconds}s (Newest) to ${healthReport.sample_stats.oldest_kill_age_hours}h (Oldest)`);
    console.log(`    Ingest Delay:  ${healthReport.sample_stats.avg_ingestion_delay_seconds}s (Avg)`);

    // Combine data quality into a single summary line
    const issues = [];
    if (healthReport.sample_stats.missing_data_count > 0) issues.push(`${healthReport.sample_stats.missing_data_count} Missing Data`);
    if (healthReport.sample_stats.incomplete_resolution_count > 0) issues.push(`${healthReport.sample_stats.incomplete_resolution_count} Incomplete Resolution`);
    if (healthReport.sample_stats.failed_lookup_count > 0) issues.push(`${healthReport.sample_stats.failed_lookup_count} Failed Lookups`);
    if (healthReport.sample_stats.missing_value_count > 0) issues.push(`${healthReport.sample_stats.missing_value_count} Missing Value`);

    if (issues.length > 0) {
        console.log(`    Top Issues:    ${issues.join(', ')}`);
    } else if (healthReport.errors === 0 && healthReport.warnings === 0) {
        console.log(`    Top Issues:    None detected`);
    }

    // 4. Less Pertinent: DB Totals
    console.log('\n' + hr);
    console.log('🗃️  DATABASE TOTALS (Context)');
    console.log(hr);
    console.log(`    Total Kills:       ${overallStats.total_killmails.toLocaleString()}`);
    console.log(`    Resolved Entities: ${overallStats.total_resolved_entities.toLocaleString()}`);
    console.log(`    Newest Kill in DB: ${overallStats.newest_kill.timestamp} (ID: ${overallStats.newest_kill.id})`);

    // 5. Least Pertinent: Individual Debugging
    console.log('\n' + hr);
    console.log('📋 INDIVIDUAL KILLMAIL DEBUGGING (Sample)');
    console.log(hr);

    for (const km of healthReport.killmails) {
        const statusIcon = km.status === 'healthy' ? '✅' : km.status === 'warning' ? '⚠️' : '❌';
        console.log(`\n${statusIcon} Killmail #${km.index_position}: ${km.killmail_id} [${km.status.toUpperCase()}]`);

        if (km.details.killmail_time) {
            console.log(`    Time: ${km.details.killmail_time}`);
            console.log(`    Age: ${km.details.age_from_now_seconds}s | Ingestion Delay: ${km.details.ingestion_delay_seconds}s`);
        }

        if (km.details.total_value_isk) {
            console.log(`    Value: ${km.details.total_value_isk} ISK | Solo: ${km.details.is_solo_kill ? 'Yes' : 'No'}`);
        }

        if (km.details.attacker_count) {
            const npcNote = km.details.npc_attacker_count > 0 ? ` (${km.details.npc_attacker_count} NPCs)` : '';
            console.log(`    Attackers: ${km.details.attacker_count}${npcNote}`);
        }

        if (km.details.victim_is_npc) {
            const indexStatus = km.details.npc_correctly_not_indexed ? '✅ Not indexed' : '❌ Incorrectly indexed';
            console.log(`    🤖 Victim: NPC (${indexStatus})`);
        }

        if (km.details.has_failed_lookups) {
            console.log(`    ℹ️   Contains cached failed lookups (deleted chars/invalid IDs)`);
        }

        if (km.details.note_zero_isk) {
            console.log(`    Note: ${km.details.note_zero_isk}`);
        }

        if (km.issues.length > 0) {
            console.log(`    Issues:`);
            km.issues.forEach(issue => console.log(`        ${issue}`));
        }

        if (km.warnings.length > 0) {
            console.log(`    Warnings:`);
            km.warnings.forEach(warning => console.log(`        ${warning}`));
        }
    }

    console.log(`\n${hr}`);
    console.log('✅ Health check complete');
    console.log(hr + '\n');

    return [{ json: healthReport }];

} catch (error) {
    console.error('❌ CRITICAL ERROR during health check:', error.message);
    console.error(error.stack);
    return [{ json: { 
        status: 'failed', 
        error: error.message, 
        stack: error.stack,
        timestamp: new Date().toISOString()
    }}];

} finally {
    if (redis) {
        await redis.quit();
        console.log('🔌 Redis connection closed.');
    }
}

