function formatTimeAgo(totalSeconds) {
    // totalSeconds is the calculated age in seconds
    const ageSeconds = Math.round(totalSeconds);

    if (ageSeconds < 60) {
        return `${ageSeconds} sec ago`;
    }

    const minutes = Math.floor(ageSeconds / 60);
    const seconds = ageSeconds % 60;

    if (minutes < 60) {
        return `${minutes} min, ${seconds} sec ago`;
    }

    const hours = Math.floor(minutes / 60);
    const remainingMinutes = minutes % 60;

    return `${hours} hr, ${remainingMinutes} min ago`;
}

