    const killIdData = await redis.zrevrange('intel:kills:all', 0, 4, 'WITHSCORES');

    if (!killIdData || killIdData.length === 0) {
        console.log('No killmails found in index.');
        return [{ json: { status: 'empty', message: 'No killmails found in index.' } }];
    }

    // 3. Prepare IDs and timestamps
    const killIds = [];
    const timestampMap = new Map(); // Stores {ID: ZSCORE}
    for (let i = 0; i < killIdData.length; i += 2) {
        const id = killIdData[i];
        const timestamp = parseInt(killIdData[i + 1]);
        killIds.push(id);
        timestampMap.set(id, timestamp);
    }

    // 4. Fetch the full killmail data
    console.log(`Fetching full data for ${killIds.length} killmails from intel:kill:data...`);
    const killmailStrings = await redis.hmget('intel:kill:data', ...killIds);

    // 5. Process and find unique system IDs
    const killmails = [];
    const systemIdsToFetch = new Set();
    for (const kmString of killmailStrings) {
        if (kmString) {
            try {
                const km = JSON.parse(kmString);
                killmails.push(km);
                if (km.solar_system_id) {
                    systemIdsToFetch.add(km.solar_system_id.toString());
                }
            } catch (e) {
                console.warn(`Failed to parse a killmail, skipping. Error: ${e.message}`);
            }
        }
    }

    // 6. Fetch security data for all systems in one go
    const systemDetailsMap = new Map();
    if (systemIdsToFetch.size > 0) {
        console.log(`Fetching system details for ${systemIdsToFetch.size} systems...`);
        const systemDetailsStrings = await redis.hmget('eve:system_details', ...Array.from(systemIdsToFetch));
        const systemIdsArray = Array.from(systemIdsToFetch);

        for (let i = 0; i < systemDetailsStrings.length; i++) {
            const sysId = systemIdsArray[i];
            const sysString = systemDetailsStrings[i];
            if (sysString) {
                try {
                    systemDetailsMap.set(sysId, JSON.parse(sysString));
                } catch (e) {
                    console.warn(`Failed to parse system details for ${sysId}`);
                }
            }
        }
    }

    // 7. Format the final report
    const now = Date.now(); // Current time in milliseconds
    const killmailReports = [];

    for (const km of killmails) {
        const killTimestamp = timestampMap.get(km.killmail_id.toString());

        let killTimestampMs;

        // 🟢 TRANSITION LOGIC: Determine if the score is MS or Seconds
        // If the score is extremely large (e.g., > Year 2033 in MS), assume it's the old millisecond format.
        if (killTimestamp > 2000000000000) { 
            killTimestampMs = killTimestamp;
        } else {
            // New, correct score (seconds) - multiply by 1000
            killTimestampMs = killTimestamp * 1000;
        }

        // Calculate the age in seconds
        const ageSecondsRaw = Math.round((now - killTimestampMs) / 1000); 

        // Handle negative age resulting from corrupted ZSCOREs
        let ageString;
        if (ageSecondsRaw < 0) {
            ageString = 'Age Data Corrupted (Waiting for fresh data)';
        } else {
            ageString = formatTimeAgo(ageSecondsRaw);
        }

        // Get security info
        const systemInfo = systemDetailsMap.get(km.solar_system_id.toString());
        const security = systemInfo ? (systemInfo.security ?? 0).toFixed(2) : 'N/A';

        // Summarize attackers
        const totalAttackers = km.attackers?.length || 0;
        const playerAttackers = km.attackers?.filter(a => !a.is_npc).length || 0;

        const report = {
            killmail_id: km.killmail_id,
            kill_time: km.killmail_time,
            age: ageString, // Use the safely determined age string
            victim: {
                name: km.victim?.character_name || 'Unknown Victim',
                ship: km.victim?.ship_type_name || 'Unknown Ship',
                corp: km.victim?.corporation_name || 'Unknown Corp',
                alliance: km.victim?.alliance_name || 'None'
            },
            location: {
                system: km.solar_system_name || 'Unknown System',
                security: security // Use the correctly fetched security
            },
            engagement: {
                total_attackers: totalAttackers,
                player_attackers: playerAttackers,
                is_solo: km.is_solo || false
            },
            value: `${(km.total_value || 0).toLocaleString(undefined, { maximumFractionDigits: 0 })} ISK`
        };

        killmailReports.push(report);
    }

    console.log('✅ Report generated.');
    return killmailReports.map(km => ({ json: km }));

} catch (error) {
    console.error('❌ Error fetching last 5 kills:', error.message);
    return [{ json: { status: 'failed', error: error.message, stack: error.stack } }];
} finally {
    // 8. Disconnect
    if (redis) {
        console.log('🔌 Disconnecting from Redis...');
        await redis.quit();
    }
}
